/* Darsi — Inhalt DEUTSCH (übersetzt aus dem Französischen, Referenzsprache).
   Quellen : 'q:S:V' = Vers, 'h:name' = Hadith, 'f:name' = Hinweis. Von einer kompetenten Person prüfen lassen. */
'use strict';
CONTENU.de={
lecons:{
/* ===================== RAMADAN & FASTEN ===================== */
'r-bienvenue':{titre:"Der Monat Ramadan",
 texte:["Der Ramadan ist der 9. Monat des islamischen Kalenders, der Hidschri-Kalender genannt wird. Dieser Kalender richtet sich nach dem Mond: Jeder Monat beginnt mit dem Erscheinen der neuen Mondsichel.",
  "Das Mondjahr hat ungefähr 354 Tage. Deshalb rückt der Ramadan in unserem Kalender jedes Jahr um etwa zehn Tage nach vorne.",
  "In diesem Monat begann die Offenbarung des Korans. Das Fasten im Ramadan wurde im 2. Jahr nach der Hidschra zur Pflicht."],
 retenir:"Der Ramadan ist der 9. Mondmonat, der Monat des Korans und des Fastens.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"An welcher Stelle steht der Monat Ramadan im islamischen Kalender (Hidschri-Kalender)?",c:["Der 9. Monat","Der 1. Monat","Der 12. Monat","Der 7. Monat"],b:0,e:"Der Ramadan ist der 9. Monat. Der 1. Monat des Hidschri-Jahres ist Muharram.",s:['f:mois']},
  {q:"Nach welchem Himmelskörper richtet sich der islamische Kalender (Hidschri-Kalender)?",c:["Nach dem Mond","Nach der Sonne","Nach den Sternen","Nach keinem Himmelskörper"],b:0,e:"Jeder Monat beginnt mit dem Erscheinen der neuen Mondsichel.",s:['q:2:189','h:croissant']},
  {q:"Warum rückt das Datum des Ramadan jedes Jahr um etwa 11 Tage nach vorne?",c:["Weil das Mondjahr kürzer ist als das Sonnenjahr","Weil die Gelehrten es jedes Jahr verschieben","Weil das Hidschri-Jahr 13 Monate hat","Weil man dem persischen Sonnenkalender folgt"],b:0,e:"Das Mondjahr hat etwa 354 Tage, also etwa 11 Tage weniger als das Sonnenjahr.",s:['q:9:36']},
  {q:"Welches große Ereignis begann im Monat Ramadan?",c:["Die Offenbarung des Korans","Der Bau der Kaaba","Die Hidschra nach Medina","Die Schlacht von Uhud"],b:0,e:"Die Offenbarung des Korans begann im Ramadan.",s:['q:2:185']},
  {q:"Wie viele Monate hat das islamische Jahr (Hidschri-Jahr)?",c:["12","10","13","11"],b:0,e:"Das Hidschri-Jahr hat 12 Mondmonate.",s:['q:9:36']},
  {q:"An welchem Zeichen beginnt man laut dem Hadith mit dem Fasten im Ramadan?",c:["Wenn man die neue Mondsichel sieht","Wenn man den Vollmond sieht","Jedes Jahr am 15. Schaban","Nach dem ersten Freitag, der auf Schaban folgt"],b:0,e:"„Fastet, wenn ihr ihn seht“: Gemeint ist die Mondsichel.",s:['h:croissant']},
  {q:"Wie heißt der Monat nach dem Ramadan, dessen 1. Tag das Ramadanfest (Eid al-Fitr) ist?",c:["Schawwal","Schaban","Radschab","Muharram"],b:0,e:"Der 1. Schawwal ist der Tag des Ramadanfests (Eid al-Fitr).",s:['f:mois']},
  {q:"Welcher Monat des islamischen Kalenders kommt direkt vor dem Ramadan?",c:["Schaban","Schawwal","Dhul-Hiddscha","Safar"],b:0,e:"Schaban ist der 8. Monat, direkt vor dem Ramadan.",s:['f:mois']},
  {q:"In welchem Jahr nach der Hidschra wurde das Fasten im Ramadan zur Pflicht?",c:["Im Jahr 2","Im Jahr 1","Im Jahr 10","Im Jahr 8"],b:0,e:"Das Fasten im Ramadan wurde in Medina vorgeschrieben, im Jahr 2 nach der Hidschra.",s:['f:jeune2']},
  {q:"Wie viele Tage kann der Monat Ramadan dauern?",c:["29 oder 30 Tage","Immer 30 Tage","28 Tage","31 Tage"],b:0,e:"Ein Mondmonat dauert 29 oder 30 Tage, je nachdem, wann die nächste Mondsichel erscheint.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"Wer muss fasten?",
 texte:["Das Fasten im Ramadan ist Pflicht für jeden Muslim, der die Pubertät erreicht hat, geistig gesund und zum Fasten fähig ist.",
  "Der Kranke und der Reisende dürfen das Fasten auslassen und die Tage später nachholen. Die Frau während ihrer Periode fastet nicht und holt die Tage danach nach.",
  "Wer niemals fasten kann, zum Beispiel ein sehr alter Mensch, speist für jeden versäumten Tag einen Armen: Das ist die Fidya."],
 retenir:"Es gibt Erleichterungen: Allah will für uns die Erleichterung.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Was muss der Reisende tun, der im Ramadan an einigen Tagen nicht gefastet hat?",c:["Diese Tage später nachholen","Gar nichts","Eine Geldstrafe zahlen","Doppelt so viel fasten"],b:0,e:"Er holt nach dem Ramadan die gleiche Anzahl Tage nach.",s:['q:2:184']},
  {q:"Wie heißt die Ersatzleistung, bei der man für jeden versäumten Fastentag einen Armen speist?",c:["Die Fidya","Die Sadaqa","Die Zakat al-Fitr","Die Kaffara"],b:0,e:"Die Fidya betrifft vor allem diejenigen, die nie nachholen können, wie sehr alte Menschen.",s:['q:2:184']},
  {q:"Ist das Fasten im Ramadan Pflicht für ein Kind, das die Pubertät noch nicht erreicht hat?",c:["Nein, aber man kann es daran gewöhnen","Ja, ab 7 Jahren","Ja, aber nur am Freitag","Nur in den letzten zehn Tagen"],b:0,e:"Es ist keine Pflicht. Die Gefährten gewöhnten ihre Kinder jedoch an das Fasten, zum Beispiel am Tag von Aschura.",s:['h:enfants']},
  {q:"Was tut die Frau im Ramadan, wenn sie ihre Periode hat?",c:["Sie fastet nicht und holt die Tage danach nach","Sie fastet trotzdem","Sie holt niemals nach","Sie fastet den halben Tag"],b:0,e:"Sie fastet nicht und holt die versäumten Tage nach dem Ramadan nach.",s:['h:regles']},
  {q:"Muss der Kranke, der im Ramadan nicht fastet, die versäumten Tage nachholen?",c:["Ja, sobald er kann","Nein, niemals","Ja, aber doppelt","Nein, er zahlt immer eine Geldstrafe"],b:0,e:"Er holt die gleiche Anzahl Tage nach, sobald er dazu fähig ist.",s:['q:2:184']},
  {q:"Muss die Frau die Gebete nachholen, die sie während ihrer Periode nicht verrichtet hat?",c:["Nein, sie holt nur das Fasten nach","Ja, alle Gebete","Ja, die Hälfte der Gebete","Nur das Freitagsgebet"],b:0,e:"Sie holt das Fasten nach, aber nicht das Gebet.",s:['h:regles']},
  {q:"Was will Allah laut dem Vers über das Fasten für die Gläubigen?",c:["Die Erleichterung","Die Erschwernis","Die Müdigkeit","Den Reichtum"],b:0,e:"„Allah will für euch Erleichterung; Er will für euch keine Erschwernis.“",s:['q:2:185']},
  {q:"Ein sehr alter Mensch, der nie mehr fasten kann: Was tut er?",c:["Er speist für jeden Tag einen Armen","Er fastet trotzdem","Er muss nichts tun","Er holt nach dem nächsten Ramadan nach"],b:0,e:"Das ist die Fidya: eine Mahlzeit für einen Armen pro nicht gefastetem Tag.",s:['q:2:184']},
  {q:"Für wen ist das Fasten im Ramadan Pflicht?",c:["Für den Muslim, der die Pubertät erreicht hat, geistig gesund und zum Fasten fähig ist","Für alle Kinder","Nur für Männer","Nur für diejenigen, die den Hadsch gemacht haben"],b:0,e:"Das sind die Bedingungen, die die Gelehrten festgelegt haben.",s:['f:conditions']},
  {q:"Wurde das Fasten laut dem Koran schon vor den Muslimen vorgeschrieben?",c:["Ja, denen, die vor ihnen waren","Nein, niemals","Nur den Leuten von Mekka","Nur dem Volk von Nuh"],b:0,e:"„Euch ist das Fasten vorgeschrieben, so wie es denen vor euch vorgeschrieben war.“",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Was das Fasten bricht",
 texte:["Das Fasten beginnt in der Morgendämmerung, zur Zeit des Fadschr-Gebets, und endet bei Sonnenuntergang, zur Zeit des Maghrib-Gebets.",
  "Absichtliches Essen, Trinken oder Geschlechtsverkehr während des Tages bricht das Fasten.",
  "Wer aus Vergesslichkeit isst oder trinkt, setzt sein Fasten fort: Es bleibt gültig."],
 retenir:"Essen oder Trinken aus Vergesslichkeit macht das Fasten nicht ungültig.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"Zu welcher Tageszeit beginnt das Fasten im Ramadan?",c:["In der Morgendämmerung (Fadschr)","Um Mitternacht","Bei Sonnenaufgang","Am Mittag"],b:0,e:"Das Fasten beginnt in der Morgendämmerung, wenn sich der weiße Faden vom schwarzen Faden unterscheiden lässt.",s:['q:2:187']},
  {q:"Wann bricht man das Fasten im Ramadan?",c:["Bei Sonnenuntergang (Maghrib)","Bei völliger Dunkelheit (Ischa)","Um 16 Uhr","Mitten in der Nacht"],b:0,e:"Man bricht das Fasten, sobald die Sonne untergegangen ist.",s:['h:coucher']},
  {q:"Ein Fastender trinkt Wasser, weil er vergessen hat, dass er fastet. Was wird aus seinem Fasten?",c:["Es bleibt gültig","Es ist ungültig","Er muss es doppelt nachholen","Es hängt von der Menge ab"],b:0,e:"Er vollendet sein Fasten: Allah hat ihm zu essen und zu trinken gegeben.",s:['h:oubli']},
  {q:"Was passiert, wenn ein Fastender mitten an einem Ramadantag absichtlich isst?",c:["Sein Fasten ist gebrochen","Es ändert sich nichts","Es ist erlaubt, wenn er in der Moschee ist","Es ist nach dem Dhuhr-Gebet erlaubt"],b:0,e:"Absichtliches Essen während des Tages bricht das Fasten.",s:['q:2:187']},
  {q:"Bis wann darf man laut dem Koran in den Nächten des Ramadan essen und trinken?",c:["Bis sich der weiße Faden der Morgendämmerung vom schwarzen Faden der Nacht unterscheiden lässt","Bis Mitternacht","Bis zum Sonnenaufgang","Bis zum Ischa-Gebet"],b:0,e:"Das ist das Bild aus Vers 187 der Sure Al-Baqara.",s:['q:2:187']},
  {q:"Wofür steht im Vers über das Fasten „der weiße Faden“?",c:["Für das Licht der Morgendämmerung","Für einen echten Wollfaden","Für die Mondsichel","Für den ersten Abendstern"],b:0,e:"Der weiße Faden ist die Helligkeit der Morgendämmerung, der schwarze Faden die Dunkelheit der Nacht.",s:['q:2:187']},
  {q:"Darf man im Ramadan nachts, nach Sonnenuntergang, essen und trinken?",c:["Ja, bis zur Morgendämmerung","Nein, während des ganzen Monats nie","Nur Wasser","Nur nach dem Tarawih-Gebet"],b:0,e:"Das Fasten betrifft nur den Tag, von der Morgendämmerung bis zum Sonnenuntergang.",s:['q:2:187']},
  {q:"Wer hat laut dem Hadith demjenigen „zu essen und zu trinken gegeben“, der beim Fasten aus Vergesslichkeit isst oder trinkt?",c:["Allah","Seine Familie","Ein Engel","Niemand"],b:0,e:"Sein Fasten bleibt gültig: Allah hat ihm zu essen und zu trinken gegeben.",s:['h:oubli']},
  {q:"Ist Geschlechtsverkehr zwischen Eheleuten an den Tagen des Ramadan erlaubt?",c:["Nein, er bricht das Fasten","Ja, jederzeit","Ja, am Nachmittag","Nur am Tag von Aschura"],b:0,e:"Vers 187 erlaubt ihn in den Nächten des Ramadan; während des Tages bricht er das Fasten.",s:['q:2:187']},
  {q:"Welches Gebet markiert das Ende des Fastentages?",c:["Das Maghrib-Gebet","Das Fadschr-Gebet","Das Dhuhr-Gebet","Das Ischa-Gebet"],b:0,e:"Maghrib ist das Gebet bei Sonnenuntergang, die Zeit des Fastenbrechens.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"Suhur und Iftar",
 texte:["Der Suhur ist die Mahlzeit vor der Morgendämmerung. Der Prophet ﷺ hat dazu ermutigt, ihn einzunehmen, denn er enthält Segen.",
  "Der Iftar ist das Fastenbrechen bei Sonnenuntergang. Es wird empfohlen, ihn nicht hinauszuzögern.",
  "Die Sunna ist, das Fasten mit frischen Datteln zu brechen, sonst mit getrockneten Datteln, sonst mit einigen Schlucken Wasser."],
 retenir:"Suhur vor der Morgendämmerung. Iftar gleich bei Sonnenuntergang, mit Datteln.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"Wie heißt die Mahlzeit, die man im Ramadan vor der Morgendämmerung einnimmt?",c:["Der Suhur","Der Iftar","Die Walima","Die Aqiqa"],b:0,e:"Der Suhur ist die Mahlzeit am Ende der Nacht, vor dem Fadschr.",s:['h:suhur']},
  {q:"Was enthält die Suhur-Mahlzeit laut dem Hadith?",c:["Segen","Eine Pflicht","Nichts Besonderes","Eine Prüfung"],b:0,e:"„Nehmt den Suhur ein, denn im Suhur liegt Segen.“",s:['h:suhur']},
  {q:"Womit brach der Prophet ﷺ sein Fasten am liebsten?",c:["Mit Datteln","Mit Kamelmilch","Mit Harira","Mit Brot"],b:0,e:"Mit frischen Datteln, sonst mit getrockneten Datteln, sonst mit einigen Schlucken Wasser.",s:['h:dattes']},
  {q:"Soll man das Fastenbrechen (Iftar) nach Sonnenuntergang hinauszögern?",c:["Nein, es wird empfohlen, sich zu beeilen","Ja, um eine Stunde","Ja, bis zum Ischa","Das spielt keine Rolle"],b:0,e:"Es wird empfohlen, das Fasten gleich bei Sonnenuntergang zu brechen.",s:['h:hater']},
  {q:"Wie heißt die Mahlzeit, mit der man bei Sonnenuntergang das Fasten bricht?",c:["Der Iftar","Der Suhur","Der Ghusl","Der Dhikr"],b:0,e:"Der Iftar ist das Fastenbrechen.",s:['h:hater']},
  {q:"Womit brach der Prophet ﷺ sein Fasten, wenn es keine Datteln gab?",c:["Mit einigen Schlucken Wasser","Mit Honig","Mit Ziegenmilch","Mit Feigen"],b:0,e:"Mit frischen Datteln, sonst getrockneten, sonst mit einigen Schlucken Wasser.",s:['h:dattes']},
  {q:"Brach der Prophet ﷺ sein Fasten vor oder nach dem Maghrib-Gebet?",c:["Vor dem Gebet","Nach dem Gebet","Am nächsten Tag","Nach dem Ischa-Gebet"],b:0,e:"Er brach sein Fasten vor dem Gebet, mit einigen Datteln.",s:['h:dattes']},
  {q:"Laut dem Hadith bleiben die Menschen, solange sie sich mit dem Fastenbrechen beeilen, …",c:["im Guten","im Zweifel","in Gefahr","ohne Belohnung"],b:0,e:"„Die Menschen werden nicht aufhören, im Guten zu sein, solange sie sich mit dem Fastenbrechen beeilen.“",s:['h:hater']},
  {q:"Ist der Suhur Pflicht, damit das Fasten gültig ist?",c:["Nein, aber er ist sehr empfohlen","Ja, sonst ist das Fasten ungültig","Ja, nur am ersten Tag","Er ist verboten"],b:0,e:"Er ist Sunna: Der Prophet ﷺ hat wegen seines Segens dazu ermutigt.",s:['h:suhur']},
  {q:"Welche Art von Datteln bevorzugte der Prophet ﷺ zum Fastenbrechen?",c:["Frische Datteln (Rutab)","Getrocknete Datteln (Tamr)","Getrocknete Feigen","Rosinen"],b:0,e:"Er begann mit frischen Datteln; wenn keine da waren, mit getrockneten Datteln.",s:['h:dattes']}
 ]},
'r-merites':{titre:"Die Vorzüge des Fastens",
 texte:["Allah hat das Fasten vorgeschrieben, damit der Gläubige Gottesfurcht (Taqwa) erlangt: das Bewusstsein für Allah in jeder Handlung.",
  "Der Prophet ﷺ hat demjenigen die Vergebung seiner vergangenen Sünden versprochen, der den Ramadan im Glauben und in der Hoffnung auf Allahs Belohnung fastet.",
  "Am Ende des Monats entrichtet jeder Muslim die Zakat al-Fitr vor dem Festgebet. Sie reinigt den Fastenden und gibt den Armen zu essen."],
 retenir:"Das Fasten führt zur Gottesfurcht. Die Zakat al-Fitr wird vor dem Festgebet entrichtet.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"Zu welchem Zweck hat Allah laut dem Koran das Fasten vorgeschrieben?",c:["Um Gottesfurcht (Taqwa) zu erlangen","Nur um den Körper zu reinigen","Um an die Hidschra zu erinnern","Um die Zakat zu ersetzen"],b:0,e:"Der Vers, der das Fasten vorschreibt, endet mit der Hoffnung, Gottesfurcht zu erlangen.",s:['q:2:183']},
  {q:"Was gewinnt laut dem Hadith derjenige, der den Ramadan im Glauben und in der Hoffnung auf Allahs Belohnung fastet?",c:["Seine vergangenen Sünden werden vergeben","Er muss nicht mehr beten","Er ist von der Zakat befreit","Nichts Besonderes"],b:0,e:"Seine vergangenen Sünden werden ihm vergeben.",s:['h:pardon']},
  {q:"Wann muss man die Zakat al-Fitr entrichten?",c:["Vor dem Gebet des Ramadanfests (Eid al-Fitr)","Einen Monat nach dem Ramadan","Nur zu Beginn des Ramadan","Irgendwann im Jahr"],b:0,e:"Der Prophet ﷺ befahl, sie zu entrichten, bevor die Menschen zum Festgebet hinausgehen.",s:['h:fitr']},
  {q:"Was bedeutet das Wort „Taqwa“?",c:["Gottesfurcht, das Bewusstsein für Allah","Die Geduld (Sabr)","Die Dankbarkeit (Schukr)","Die Reue (Tawba)"],b:0,e:"Taqwa ist die ehrfürchtige Furcht vor Allah, die zum Guten antreibt.",s:['q:2:183']},
  {q:"Wer muss die Zakat al-Fitr entrichten?",c:["Jeder Muslim, klein oder groß, Mann oder Frau","Nur die Reichen","Nur die Männer","Nur wer den ganzen Monat gefastet hat"],b:0,e:"Der Hadith schreibt sie jedem Muslim vor; das Familienoberhaupt entrichtet sie für seine Angehörigen.",s:['h:fitr']},
  {q:"Welche Menge an Nahrung legt der Hadith für die Zakat al-Fitr fest?",c:["Ein Sa'","Ein Mithqal Gold","Ein Mudd Weizen","Ein Dirham Silber"],b:0,e:"Ein Sa' ist ein Maß von etwa viermal dem Inhalt beider hohlen Hände.",s:['h:fitr']},
  {q:"Welche Lebensmittel werden im Hadith über die Zakat al-Fitr genannt, den Ibn Umar überliefert hat?",c:["Datteln oder Gerste","Reis oder Couscous","Fleisch oder Fisch","Milch oder Honig"],b:0,e:"Ein Sa' Datteln oder ein Sa' Gerste.",s:['h:fitr']},
  {q:"Unter welchen Bedingungen tilgt das Fasten im Ramadan laut dem Hadith die vergangenen Sünden?",c:["Mit Glauben und der Hoffnung auf Allahs Belohnung","Wenn man schweigend fastet","Wenn man 40 Tage fastet","Ohne jede Bedingung"],b:0,e:"Man muss im Glauben und in der Hoffnung auf Allahs Belohnung fasten.",s:['h:pardon']},
  {q:"Was ist laut dem Hadith von Ibn Abbas der Zweck der Zakat al-Fitr?",c:["Den Fastenden reinigen und den Armen zu essen geben","Den Bau von Moscheen finanzieren","Das Fasten der Kranken ersetzen","Den Imam des Tarawih belohnen"],b:0,e:"Sie reinigt den Fastenden von seinem leeren Gerede und gibt den Armen zu essen.",s:['h:fitr_but']},
  {q:"Mit welchem Anruf beginnt der Vers, der das Fasten im Ramadan vorschreibt?",c:["„O ihr, die ihr glaubt!“","„O ihr Menschen!“","„O Prophet!“","„O Kinder Adams!“"],b:0,e:"Vers 183 der Sure Al-Baqara beginnt mit „O ihr, die ihr glaubt!“.",s:['q:2:183']}
 ]},
'r-nuits':{titre:"Die Nächte des Ramadan",
 texte:["Die Nächte des Ramadan sind eine Gelegenheit, mehr zu beten. Ihr Nachtgebet heißt Tarawih. Der Prophet ﷺ hat demjenigen Vergebung versprochen, der die Nächte des Ramadan im Glauben und in der Hoffnung auf Belohnung im Gebet verbringt.",
  "In den letzten zehn Nächten verdoppelte er seine Anstrengungen: Er wachte nachts im Gebet und weckte seine Familie.",
  "Er machte auch I'tikaf: einen spirituellen Rückzug in die Moschee während der letzten zehn Tage, und das bis zum Ende seines Lebens."],
 retenir:"Tarawih, die letzten zehn Nächte, I'tikaf: Die Nächte des Ramadan werden im Gebet verbracht.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"Wie nennt man das Nachtgebet, das im Ramadan verrichtet wird?",c:["Tarawih","Das Duha-Gebet","Das Istikhara-Gebet","Das Totengebet"],b:0,e:"Tarawih ist das Gebet der Ramadannächte.",s:['h:qiyam']},
  {q:"Was gewinnt laut dem Hadith derjenige, der die Nächte des Ramadan im Glauben und in der Hoffnung auf Belohnung im Gebet verbringt?",c:["Seine vergangenen Sünden werden vergeben","Einen Platz in der ersten Reihe der Moschee","Er muss nicht mehr fasten","Nichts Besonderes"],b:0,e:"Seine vergangenen Sünden werden ihm vergeben.",s:['h:qiyam']},
  {q:"Was ist I'tikaf?",c:["Ein spiritueller Rückzug in die Moschee","Eine Reise nach Mekka","Das Fasten von Aschura","Eine Spende"],b:0,e:"Man bleibt in der Moschee, um sich dem Gottesdienst zu widmen.",s:['h:itikaf']},
  {q:"In welchem Zeitraum des Ramadan machte der Prophet ﷺ I'tikaf?",c:["In den letzten zehn Tagen","In den ersten zehn Tagen","Nur am ersten Tag","Nach dem Fest"],b:0,e:"Er machte ihn in den letzten zehn Tagen des Ramadan.",s:['h:itikaf']},
  {q:"Was tat der Prophet ﷺ in den letzten zehn Nächten des Ramadan?",c:["Er wachte im Gebet und weckte seine Familie","Er reiste","Er ging früher schlafen","Er hörte auf zu fasten"],b:0,e:"Er verdoppelte seine Anstrengungen im Gottesdienst.",s:['h:dixnuits']},
  {q:"Hat der Prophet ﷺ I'tikaf bis zum Ende seines Lebens gemacht?",c:["Ja, bis zu seinem Tod","Nein, nur einmal","Nein, niemals","Nur in Mekka"],b:0,e:"Aischa berichtet, dass er ihn praktizierte, bis Allah ihn zu Sich nahm.",s:['h:itikaf']},
  {q:"Wo macht man I'tikaf?",c:["In der Moschee","Zu Hause","In der Höhle Hira","Auf dem Friedhof"],b:0,e:"Der Koran erwähnt diejenigen, die sich in den Moscheen zurückziehen.",s:['q:2:187']},
  {q:"Welche sehr wichtige Nacht befindet sich unter den letzten zehn Nächten des Ramadan?",c:["Laylat al-Qadr, die Nacht der Bestimmung","Die Nacht der Hidschra","Die Nacht vor dem Opferfest","Die Nacht des Maulid"],b:0,e:"Man soll sie in den ungeraden Nächten der letzten zehn Nächte suchen.",s:['h:qadr']},
  {q:"Ist das Tarawih-Gebet Pflicht?",c:["Nein, es ist ein freiwilliges, sehr empfohlenes Gebet","Ja, wie die fünf Gebete","Ja, aber nur in der Moschee","Es ist verboten"],b:0,e:"Der Prophet ﷺ betete es einige Nächte in der Gemeinschaft und hörte dann auf, aus Sorge, es könnte zur Pflicht werden.",s:['h:tarawih']},
  {q:"Warum hörte der Prophet ﷺ nach einigen Nächten auf, das Tarawih in der Gemeinschaft zu leiten?",c:["Aus Sorge, es könnte zur Pflicht werden","Weil er krank war","Weil die Moschee zu klein war","Weil der Ramadan zu Ende war"],b:0,e:"Er befürchtete, es könnte seiner Gemeinschaft zur Pflicht gemacht werden.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, die Nacht der Bestimmung",
 texte:["Laylat al-Qadr, die Nacht der Bestimmung, ist die Nacht, in der die Offenbarung des Korans begann.",
  "Allah sagt, dass sie „besser als tausend Monate“ ist. Die Engel steigen in ihr herab, und sie ist Frieden bis zum Anbruch der Morgendämmerung. Ihr ist eine ganze Sure gewidmet: die Sure Al-Qadr (97).",
  "Man sucht sie in den letzten zehn Nächten des Ramadan, vor allem in den ungeraden Nächten, und betet und bittet in ihnen besonders viel."],
 retenir:"Besser als tausend Monate. Man sucht sie in den ungeraden Nächten der letzten zehn Nächte.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Laut dem Koran ist die Nacht der Bestimmung (Laylat al-Qadr) besser als welcher Zeitraum?",c:["Tausend Monate","Hundert Tage","Ein Jahr","Zehn Nächte"],b:0,e:"Sie ist besser als tausend Monate, also mehr als 83 Jahre.",s:['q:97:3']},
  {q:"Welche Sure des Korans ist der Nacht der Bestimmung (Laylat al-Qadr) gewidmet?",c:["Al-Qadr","Al-Fatiha","Al-Ikhlas","Ya-Sin"],b:0,e:"Die Sure 97, Al-Qadr, trägt den Namen dieser Nacht.",s:['q:97:1']},
  {q:"In welchen Nächten des Ramadan soll man vorrangig nach der Nacht der Bestimmung (Laylat al-Qadr) suchen?",c:["In den ungeraden Nächten der letzten zehn Nächte","In den ersten zehn Nächten","In der ersten Nacht","In der Nacht vor dem Fest"],b:0,e:"Die ungeraden der letzten zehn Nächte: 21, 23, 25, 27 und 29.",s:['h:qadr']},
  {q:"Welches Ereignis fand in der Nacht der Bestimmung (Laylat al-Qadr) statt?",c:["Der Beginn der Offenbarung des Korans","Die Hidschra nach Medina","Die Geburt des Propheten ﷺ","Die erste Pilgerfahrt"],b:0,e:"Die Offenbarung des Korans begann in dieser Nacht.",s:['q:97:1']},
  {q:"Wer steigt laut der Sure Al-Qadr in der Nacht der Bestimmung herab?",c:["Die Engel und der Geist (Dschibril)","Die Propheten","Die Dschinn","Niemand"],b:0,e:"Die Engel und der Geist steigen in ihr herab, mit der Erlaubnis ihres Herrn.",s:['q:97:4']},
  {q:"Bis wann ist die Nacht der Bestimmung laut der Sure Al-Qadr Frieden?",c:["Bis zum Anbruch der Morgendämmerung","Bis Mitternacht","Bis zum Ende des Ramadan","Bis zum Fest"],b:0,e:"„Sie ist Frieden bis zum Anbruch der Morgendämmerung.“",s:['q:97:5']},
  {q:"Wie viele Verse hat die Sure Al-Qadr?",c:["5","7","3","10"],b:0,e:"Die Sure Al-Qadr hat 5 Verse.",s:['q:97:5']},
  {q:"Tausend Monate entsprechen ungefähr wie vielen Jahren?",c:["Mehr als 83 Jahren","10 Jahren","40 Jahren","1000 Jahren"],b:0,e:"1000 Monate ÷ 12 ≈ 83 Jahre und 4 Monate: mehr als ein ganzes Leben.",s:['q:97:3']},
  {q:"Welche sind die ungeraden Nächte der letzten zehn Nächte des Ramadan?",c:["21, 23, 25, 27 und 29","20, 22, 24, 26 und 28","1, 3, 5, 7 und 9","11, 13, 15, 17 und 19"],b:0,e:"Das sind die empfohlenen Nächte, um Laylat al-Qadr zu suchen.",s:['h:qadr']},
  {q:"Welches Bittgebet lehrte der Prophet ﷺ Aischa für die Nacht der Bestimmung?",c:["„Allahumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿanni“","„Bismi Llah“","„Allahu akbar“","„Subḥana Llah“"],b:0,e:"„O Allah, Du bist der Vergebende, Du liebst das Vergeben, so vergib mir.“",s:['h:afw']}
 ]},
'r-aid':{titre:"Das Ramadanfest (Eid al-Fitr)",
 texte:["Das Ramadanfest (Eid al-Fitr) ist das Fest des Fastenbrechens. Es findet am 1. Tag des Monats Schawwal statt, direkt nach dem Ramadan.",
  "Bevor er zum Festgebet hinausging, aß der Prophet ﷺ einige Datteln, in ungerader Zahl. Die Zakat al-Fitr muss vor diesem Gebet entrichtet werden.",
  "Nach dem Fest wird empfohlen, sechs Tage im Monat Schawwal zu fasten: Zusammen mit dem Ramadan ist es, als hätte man das ganze Jahr gefastet."],
 retenir:"1. Schawwal: das Fest. Datteln vor dem Gebet, danach sechs Tage im Schawwal.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"An welchem Tag findet das Ramadanfest (Eid al-Fitr) statt?",c:["Am 1. Tag des Schawwal","Am 27. Ramadan","Am 10. Dhul-Hiddscha","Am 1. Muharram"],b:0,e:"Das Ramadanfest folgt direkt auf den Monat Ramadan.",s:['f:mois']},
  {q:"Was bedeutet „Eid al-Fitr“?",c:["Das Fest des Fastenbrechens","Das Opferfest","Das Fest der Hidschra","Das Fest der Geburt des Propheten ﷺ"],b:0,e:"Fitr bedeutet das Brechen des Fastens.",s:['f:aid']},
  {q:"Was aß der Prophet ﷺ, bevor er zum Gebet des Ramadanfests (Eid al-Fitr) hinausging?",c:["Einige Datteln","Feigen","Fleisch","Nichts, er fastete"],b:0,e:"Am Tag des Ramadanfests ging er nicht hinaus, ohne einige Datteln gegessen zu haben.",s:['h:aid_dattes']},
  {q:"In welcher Anzahl aß der Prophet ﷺ die Datteln am Morgen des Ramadanfests (Eid al-Fitr)?",c:["In ungerader Zahl","Immer zwei","Immer sieben","In gerader Zahl"],b:0,e:"Anas berichtet, dass er sie in ungerader Zahl aß.",s:['h:aid_dattes']},
  {q:"Wie viele Feste (Eid) hat der Islam im Jahr?",c:["2","1","3","5"],b:0,e:"Das Ramadanfest (Eid al-Fitr) und das Opferfest (Eid al-Adha).",s:['f:aid']},
  {q:"Wie viele Tage im Schawwal soll man laut dem Hadith nach dem Ramadan fasten?",c:["6","3","10","30"],b:0,e:"Sechs Tage im Schawwal, aufeinanderfolgend oder nicht.",s:['h:shawwal']},
  {q:"Womit ist es laut dem Hadith gleichzusetzen, den Ramadan und danach sechs Tage im Schawwal zu fasten?",c:["Mit dem Fasten des ganzen Jahres","Mit dem Hadsch","Mit einem weiteren Monat Fasten","Mit nichts Besonderem"],b:0,e:"Es ist, als hätte man das ganze Jahr gefastet.",s:['h:shawwal']},
  {q:"Vor welchem Gebet muss die Zakat al-Fitr entrichtet sein?",c:["Vor dem Festgebet","Vor dem Freitagsgebet","Vor dem Maghrib-Gebet","Vor dem Tarawih"],b:0,e:"Sie muss entrichtet werden, bevor die Menschen zum Festgebet hinausgehen.",s:['h:fitr']},
  {q:"Was tun die Gläubigen laut Vers 185 der Sure Al-Baqara, wenn die Zahl der Ramadantage vollendet ist?",c:["Sie preisen Allahs Größe","Sie beginnen von vorne zu fasten","Sie machen I'tikaf","Sie reisen nach Medina"],b:0,e:"Der Vers fordert dazu auf, Allahs Größe für die erhaltene Rechtleitung zu preisen: Das ist der Takbir des Festes.",s:['q:2:185']},
  {q:"Welches ist das andere große Fest des Islam, das während der Pilgerfahrt gefeiert wird?",c:["Das Opferfest (Eid al-Adha)","Das Ramadanfest (Eid al-Fitr)","Der Maulid","Der 1. Muharram"],b:0,e:"Das Opferfest (Eid al-Adha) findet am 10. Dhul-Hiddscha statt.",s:['f:aid']}
 ]},

/* ===================== SÄULEN & GEBET ===================== */
'p-piliers':{titre:"Die fünf Säulen des Islam",
 texte:["Der Islam beruht auf fünf Säulen, die in einem authentischen Hadith genannt werden, überliefert von al-Bukhari und Muslim.",
  "Die Schahada, das Glaubensbekenntnis. Die Salat, die fünf täglichen Gebete. Die Zakat, die Pflichtabgabe. Der Hadsch, die Pilgerfahrt nach Mekka für den, der die Mittel dazu hat. Der Saum, das Fasten im Ramadan.",
  "Diese fünf Säulen sind das Fundament der Glaubenspraxis des Muslims, das ganze Jahr über."],
 retenir:"Schahada, Salat, Zakat, Hadsch, Fasten im Ramadan.",
 sources:['h:piliers'],
 quiz:[
  {q:"Wie viele Säulen hat der Islam?",c:["5","3","4","6"],b:0,e:"Der Islam beruht auf fünf Säulen.",s:['h:piliers']},
  {q:"Wie nennt man das Fasten auf Arabisch?",c:["Saum (oder Siyam)","Salat","Zakat","Hadsch"],b:0,e:"Fasten heißt Saum oder Siyam; das ist das Wort aus dem Vers, der es vorschreibt.",s:['q:2:183']},
  {q:"Für wen ist die Pilgerfahrt nach Mekka (Hadsch) Pflicht?",c:["Für den, der die Mittel dazu hat, einmal im Leben","Für alle, jedes Jahr","Nur für Männer","Nur im Ramadan"],b:0,e:"Der Hadsch ist einmal im Leben Pflicht, für den, der körperlich und finanziell dazu fähig ist.",s:['q:3:97']},
  {q:"Wie viele Pflichtgebete verrichtet ein Muslim jeden Tag?",c:["5","3","7","2"],b:0,e:"Fadschr, Dhuhr, Asr, Maghrib und Ischa.",s:['h:cinq']},
  {q:"Was ist die erste Säule des Islam?",c:["Die Schahada, das Glaubensbekenntnis","Das Fasten","Der Hadsch","Die Zakat"],b:0,e:"Die Schahada wird im Hadith zuerst genannt.",s:['h:piliers']},
  {q:"Welche Säule des Islam ist die Pflichtabgabe?",c:["Die Zakat","Die Salat","Der Saum","Die Schahada"],b:0,e:"Die Zakat wird jedes Jahr auf Besitz entrichtet, der eine Mindestgrenze erreicht.",s:['h:piliers']},
  {q:"Welche Säule des Islam wird im Monat Ramadan praktiziert?",c:["Das Fasten (Saum)","Der Hadsch","Die Zakat","Die Schahada"],b:0,e:"Das Fasten im Ramadan ist eine der fünf Säulen.",s:['h:piliers']},
  {q:"Welche Säule des Islam besteht darin, nach Mekka zu reisen?",c:["Der Hadsch","Die Salat","Der Saum","Die Zakat"],b:0,e:"Der Hadsch ist die Pilgerfahrt zum heiligen Haus.",s:['q:3:97']},
  {q:"Wie oft im Leben ist der Hadsch laut dem Hadith Pflicht?",c:["Nur einmal","Jedes Jahr","Dreimal","Siebenmal"],b:0,e:"Der Prophet ﷺ stellte klar, dass er nicht jedes Jahr Pflicht ist.",s:['h:hajj_une']},
  {q:"Welcher Gefährte hat den Hadith über die fünf Säulen des Islam überliefert?",c:["Abdullah ibn Umar","Abu Bakr","Bilal","Khalid ibn al-Walid"],b:0,e:"Der Hadith wird von Ibn Umar überliefert.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"Die Schahada, das Glaubensbekenntnis",
 texte:["Die Schahada ist das Glaubensbekenntnis: „Asch-hadu an la ilaha illa Llah, wa asch-hadu anna Muḥammadan rasulu Llah“.",
  "Sie bedeutet: „Ich bezeuge, dass es keinen Gott gibt außer Allah, und ich bezeuge, dass Muhammad der Gesandte Allahs ist.“",
  "Sie ist die erste Säule: Durch sie tritt man in den Islam ein. Sie bekräftigt die Einheit Allahs, den Tauhid, zusammengefasst in der Sure Al-Ikhlas."],
 retenir:"La ilaha illa Llah, Muḥammadun rasulu Llah.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"Welche Säule des Islam ist das Glaubensbekenntnis?",c:["Die Schahada","Die Salat","Die Zakat","Der Hadsch"],b:0,e:"Die Schahada ist die erste Säule.",s:['h:piliers']},
  {q:"Was bedeutet „la ilaha illa Llah“?",c:["Es gibt keinen Gott außer Allah","Allah ist der Größte","Gepriesen sei Allah","Im Namen Allahs"],b:0,e:"Das ist der erste Teil der Schahada.",s:['q:47:19']},
  {q:"Was bedeutet „Muḥammadun rasulu Llah“?",c:["Muhammad ist der Gesandte Allahs","Muhammad ist ein Engel","Muhammad ist der erste Mensch","Muhammad ist ein König"],b:0,e:"Das ist der zweite Teil der Schahada.",s:['q:48:29']},
  {q:"Wie nennt man den Glauben an die Einheit Allahs?",c:["Tauhid","Hadsch","Sunna","Fiqh"],b:0,e:"Der Tauhid ist das Herz des islamischen Glaubens.",s:['q:112:1']},
  {q:"Welche Sure fasst die Einheit Allahs in vier Versen zusammen?",c:["Al-Ikhlas","Al-Fatiha","Al-Kauthar","An-Nas"],b:0,e:"Die Sure 112, Al-Ikhlas.",s:['q:112:1']},
  {q:"Aus wie vielen Teilen besteht die Schahada?",c:["Aus zwei: die Einheit Allahs und die Botschaft Muhammads ﷺ","Aus einem einzigen","Aus fünf","Aus sieben"],b:0,e:"Man bezeugt die Einheit Allahs und dann, dass Muhammad ﷺ Sein Gesandter ist.",s:['h:piliers']},
  {q:"Hat Allah laut der Sure Al-Ikhlas gezeugt oder wurde Er gezeugt?",c:["Weder das eine noch das andere","Beides","Er hat gezeugt","Er wurde gezeugt"],b:0,e:"„Er hat nicht gezeugt und ist nicht gezeugt worden.“",s:['q:112:3']},
  {q:"Was bedeutet „Asch-hadu“ am Anfang der Schahada?",c:["Ich bezeuge","Ich bete","Ich faste","Ich vergebe"],b:0,e:"Asch-hadu bedeutet „ich bezeuge, ich lege Zeugnis ab“.",s:['f:shahada']},
  {q:"Was tut ein Mensch, um in den Islam einzutreten?",c:["Er spricht die Schahada mit Überzeugung","Er fastet einen Monat","Er macht den Hadsch","Er lernt Arabisch"],b:0,e:"Die aufrichtig gesprochene Schahada lässt einen in den Islam eintreten.",s:['f:shahada']},
  {q:"Was sagt der Koran in der Sure Al Imran, Vers 144, über Muhammad ﷺ?",c:["Er ist nur ein Gesandter, vor ihm sind schon andere Gesandte dahingegangen","Er ist unsterblich","Er ist ein Engel","Er ist der erste Prophet"],b:0,e:"Muhammad ﷺ ist ein Mensch und ein Gesandter, wie diejenigen vor ihm.",s:['q:3:144']}
 ]},
'p-priere':{titre:"Das Gebet, fünf Verabredungen am Tag",
 texte:["Der Muslim betet fünfmal am Tag: Fadschr in der Morgendämmerung, Dhuhr am Mittag, Asr am Nachmittag, Maghrib bei Sonnenuntergang und Ischa in der Nacht.",
  "Jedes Gebet hat eine bestimmte Anzahl von Gebetseinheiten (Rak'at): 2 für Fadschr, 4 für Dhuhr, 4 für Asr, 3 für Maghrib und 4 für Ischa.",
  "Man betet in Richtung der Kaaba in Mekka: Das ist die Qibla. Die Zeit jedes Gebets wird durch den Adhan angekündigt. Am Freitag wird das Dhuhr-Gebet durch das Freitagsgebet (Dschumu'a) ersetzt."],
 retenir:"Fadschr 2, Dhuhr 4, Asr 4, Maghrib 3, Ischa 4 – in Richtung der Qibla.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"Wie viele Gebetseinheiten (Rak'at) hat das Pflichtgebet Fadschr?",c:["2","3","4","1"],b:0,e:"Das Fadschr-Gebet hat 2 Rak'at.",s:['f:rakat']},
  {q:"Wie viele Gebetseinheiten (Rak'at) hat das Pflichtgebet Maghrib?",c:["3","2","4","5"],b:0,e:"Maghrib ist das einzige Pflichtgebet mit 3 Rak'at.",s:['f:rakat']},
  {q:"In welche Richtung wenden sich die Muslime zum Gebet?",c:["Zur Kaaba in Mekka","Nach Jerusalem","Nach Medina","Nach Osten"],b:0,e:"Diese Richtung heißt Qibla.",s:['q:2:144']},
  {q:"Wie heißt der Ruf, der die Gebetszeit ankündigt?",c:["Der Adhan","Die Iqama","Das Du'a","Der Dhikr"],b:0,e:"Der Adhan kündigt die Zeit an; die Iqama kündigt den Beginn des Gemeinschaftsgebets an.",s:['h:adhan']},
  {q:"Wie heißt das Pflichtgebet in der Morgendämmerung?",c:["Fadschr","Dhuhr","Asr","Ischa"],b:0,e:"Fadschr wird zwischen Morgendämmerung und Sonnenaufgang gebetet.",s:['f:rakat']},
  {q:"Wie viele Gebetseinheiten (Rak'at) hat das Pflichtgebet Dhuhr?",c:["4","2","3","5"],b:0,e:"Dhuhr hat 4 Rak'at.",s:['f:rakat']},
  {q:"Wie viele Pflicht-Gebetseinheiten (Rak'at) haben die fünf Gebete eines Tages insgesamt?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 Rak'at.",s:['f:rakat']},
  {q:"Wie wurde das Gebet laut dem Koran den Gläubigen vorgeschrieben?",c:["Zu festgesetzten Zeiten","Einmal pro Woche","Wann man möchte","Nur im Ramadan"],b:0,e:"„Das Gebet ist für die Gläubigen eine zu bestimmten Zeiten festgesetzte Vorschrift.“",s:['q:4:103']},
  {q:"Welches Gemeinschaftsgebet findet jeden Freitag anstelle des Dhuhr statt?",c:["Das Freitagsgebet (Dschumu'a)","Das Festgebet","Das Tarawih","Das Gebet um Regen"],b:0,e:"Der Koran ruft dazu auf, am Freitag zum Gedenken Allahs zu eilen.",s:['q:62:9']},
  {q:"Bei welchem Ereignis wurden laut dem Hadith die fünf Gebete vorgeschrieben?",c:["Bei der Nachtreise (al-Isra' wa l-Mi'radsch)","Bei der Schlacht von Badr","Bei der Hidschra","Bei der Einnahme Mekkas"],b:0,e:"Fünfzig Gebete wurden vorgeschrieben und dann auf fünf verringert.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"Die rituelle Waschung und die Fatiha",
 texte:["Vor dem Gebet reinigt sich der Muslim mit Wasser: Das ist die rituelle Waschung (Wudu). Ohne Wasser macht man Tayammum mit sauberer Erde.",
  "Man wäscht das Gesicht, die Hände und die Unterarme bis zu den Ellbogen, streicht mit den nassen Händen über den Kopf und wäscht dann die Füße bis zu den Knöcheln.",
  "In jeder Gebetseinheit rezitiert man die Sure Al-Fatiha, „die Eröffnende“, die erste Sure des Korans, die 7 Verse hat."],
 retenir:"Kein Gebet ohne rituelle Waschung, kein Gebet ohne die Fatiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"Wie heißt die Reinigung mit Wasser vor dem Gebet?",c:["Die rituelle Waschung (Wudu)","Das Fasten","Die Zakat","Der I'tikaf"],b:0,e:"Das Wudu reinigt vor dem Gebet.",s:['q:5:6']},
  {q:"Welche Sure wird in jeder Gebetseinheit (Rak'a) rezitiert?",c:["Al-Fatiha","Al-Ikhlas","Al-Baqara","Ya-Sin"],b:0,e:"Al-Fatiha, „die Eröffnende“, wird in jeder Rak'a rezitiert.",s:['h:fatiha']},
  {q:"Mit welchem Satz beginnt die Sure Al-Fatiha?",c:["Bismi Llahi r-Raḥmani r-Raḥim","Qul huwa Llahu aḥad","Allahu akbar","Subḥana Llah"],b:0,e:"„Im Namen Allahs, des Allerbarmers, des Barmherzigen.“",s:['q:1:1']},
  {q:"Bis wohin wäscht man laut dem Koran bei der rituellen Waschung die Arme?",c:["Bis zu den Ellbogen","Bis zu den Handgelenken","Bis zu den Schultern","Nur die Finger"],b:0,e:"Vers 6 der Sure Al-Ma'ida legt es fest.",s:['q:5:6']},
  {q:"Was macht man laut dem Koran bei der rituellen Waschung mit dem Kopf?",c:["Man streicht mit den nassen Händen darüber","Man wäscht ihn dreimal vollständig","Man bedeckt ihn mit einem Turban","Man gießt Wasser über den Nacken"],b:0,e:"Das ist der Mash: mit den nassen Händen über den Kopf streichen.",s:['q:5:6']},
  {q:"Was tut man, wenn man kein Wasser findet, um sich vor dem Gebet zu reinigen?",c:["Tayammum, mit sauberer Erde","Man betet nicht","Man wartet bis zum nächsten Tag","Man betet ohne Reinigung"],b:0,e:"Derselbe Vers sieht Tayammum vor, wenn Wasser fehlt.",s:['q:5:6']},
  {q:"Nimmt Allah laut dem Hadith das Gebet dessen an, der seine rituelle Waschung verloren und nicht erneuert hat?",c:["Nein, nicht bevor er die Waschung erneuert","Ja, immer","Ja, am Freitag","Nur das Fadschr-Gebet"],b:0,e:"Das Gebet wird erst angenommen, wenn man die Waschung erneuert hat.",s:['h:wudu']},
  {q:"Wie viele Verse hat die Sure Al-Fatiha?",c:["7","5","10","3"],b:0,e:"Sie wird „die sieben wiederholten Verse“ genannt.",s:['q:15:87']},
  {q:"Was bedeutet „Al-ḥamdu li-Llahi rabbi l-ʿalamin“?",c:["Lob sei Allah, dem Herrn der Welten","Allah ist der Größte","Es gibt keinen Gott außer Allah","Ich suche Zuflucht bei Allah"],b:0,e:"Das ist der 2. Vers der Fatiha.",s:['q:1:2']},
  {q:"Was gilt laut dem Hadith das Gebet dessen, der die Fatiha nicht rezitiert?",c:["Es ist nicht gültig","Es zählt doppelt","Es ist gültig","Es zählt zur Hälfte"],b:0,e:"„Es gibt kein Gebet für den, der die Fatiha nicht rezitiert.“",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"Die Zakat, die Pflichtabgabe",
 texte:["Die Zakat ist die Pflichtabgabe, eine der fünf Säulen des Islam. Ihr Name steht für Reinigung und Wachstum: Sie reinigt den Besitz und hilft den Bedürftigsten.",
  "Sie betrifft den, dessen Ersparnisse eine Mindestgrenze (den Nisab) erreichen und ein volles Mondjahr in seinem Besitz bleiben. Für Geld beträgt sie 2,5 %.",
  "Der Koran nennt acht Gruppen von Empfängern, darunter die Armen und die Bedürftigen. Die Sadaqa dagegen ist eine freiwillige Spende, die jederzeit möglich ist."],
 retenir:"Zakat: 2,5 % der Ersparnisse, die ein Mondjahr lang den Nisab erreichen.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"Welche Säule des Islam ist die Pflichtabgabe?",c:["Die Zakat","Die Sadaqa","Der Hadsch","Der Saum"],b:0,e:"Die Zakat ist Pflicht; die Sadaqa ist freiwillig.",s:['h:piliers']},
  {q:"Wie hoch ist der Satz der Zakat auf erspartes Geld?",c:["2,5 %","10 %","20 %","5 %"],b:0,e:"Also ein Vierzigstel der Ersparnisse.",s:['f:zakat']},
  {q:"Wie nennt man die Mindestgrenze an Vermögen, ab der die Zakat fällig ist?",c:["Der Nisab","Der Sa'","Die Fidya","Der Haul"],b:0,e:"Unterhalb des Nisab ist die Zakat nicht Pflicht.",s:['f:zakat']},
  {q:"Wie lange müssen die Ersparnisse im Besitz sein, damit die Zakat fällig wird?",c:["Ein Mondjahr","Einen Monat","Zehn Jahre","Nur den Monat Ramadan"],b:0,e:"Das ist der Haul: ein volles Mondjahr.",s:['f:zakat']},
  {q:"Wie viele Gruppen von Menschen dürfen laut dem Koran die Zakat erhalten?",c:["8","5","3","12"],b:0,e:"Vers 60 der Sure At-Tauba nennt acht.",s:['q:9:60']},
  {q:"Welche gehören zu den im Koran genannten Empfängern der Zakat?",c:["Die Armen und die Bedürftigen","Die Reichsten","Die Händler","Die Imame der Moscheen"],b:0,e:"Die Armen und die Bedürftigen werden zuerst genannt.",s:['q:9:60']},
  {q:"Was ist der Unterschied zwischen Zakat und Sadaqa?",c:["Die Zakat ist Pflicht, die Sadaqa ist freiwillig","Es gibt keinen","Die Sadaqa ist Pflicht","Die Zakat ist verboten"],b:0,e:"Die Sadaqa kann jederzeit und in jeder Menge gegeben werden.",s:['f:zakat']},
  {q:"Mit welcher Handlung wird die Zakat im Koran sehr oft zusammen genannt?",c:["Mit dem Gebet","Mit dem Fasten","Mit der Pilgerfahrt","Mit der rituellen Waschung"],b:0,e:"„Und verrichtet das Gebet und entrichtet die Zakat“: Diese Formel kommt viele Male vor.",s:['q:2:43']},
  {q:"An welcher Stelle steht die Zakat in der Reihenfolge des Hadith über die Säulen?",c:["An 3. Stelle","An 1. Stelle","An 5. Stelle","An 2. Stelle"],b:0,e:"Schahada, Gebet, Zakat, Hadsch, Fasten im Ramadan.",s:['h:piliers']},
  {q:"Wofür steht das Wort „Zakat“ auf Arabisch?",c:["Für Reinigung und Wachstum","Für Geduld","Für Sieg","Für Licht"],b:0,e:"Der Koran sagt, dass die Spende reinigt (tutahhiruhum) und im Guten wachsen lässt (tuzakkihim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"Der Hadsch, die Pilgerfahrt",
 texte:["Der Hadsch ist die Pilgerfahrt nach Mekka, eine der fünf Säulen des Islam. Er ist einmal im Leben Pflicht für den, der die körperlichen und finanziellen Mittel dazu hat.",
  "Er findet im Monat Dhul-Hiddscha statt. Der Pilger tritt in den Weihezustand (Ihram) ein, umrundet die Kaaba siebenmal (Tawaf) und geht siebenmal zwischen Safa und Marwa hin und her (Sa'y). Der wichtigste Moment ist das Verweilen auf Arafa, am 9. Dhul-Hiddscha.",
  "Am nächsten Tag feiern die Muslime auf der ganzen Welt das Opferfest (Eid al-Adha), in Erinnerung an Ibrahim."],
 retenir:"Einmal im Leben. Arafa am 9. Dhul-Hiddscha, das Opferfest am 10.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"In welcher Stadt findet der Hadsch statt?",c:["Mekka","Medina","Jerusalem","Taif"],b:0,e:"Der Hadsch findet in Mekka und seiner Umgebung statt.",s:['q:3:97']},
  {q:"In welchem Monat des islamischen Kalenders findet der Hadsch statt?",c:["Dhul-Hiddscha","Ramadan","Muharram","Schawwal"],b:0,e:"Der Hadsch findet vom 8. bis 13. Dhul-Hiddscha statt.",s:['f:hajj']},
  {q:"Was ist laut dem Hadith der wichtigste Bestandteil des Hadsch?",c:["Das Verweilen auf Arafa","Das Gebet in der al-Aqsa-Moschee","Der Besuch Medinas","Der Besuch der Höhle Hira"],b:0,e:"„Der Hadsch ist Arafa.“",s:['h:arafa']},
  {q:"Welches Fest wird am Tag nach dem Tag von Arafa gefeiert?",c:["Das Opferfest (Eid al-Adha)","Das Ramadanfest (Eid al-Fitr)","Der Maulid","Der 1. Muharram"],b:0,e:"Am 10. Dhul-Hiddscha ist das Opferfest (Eid al-Adha).",s:['f:hajj']},
  {q:"Wie kehrt laut dem Hadith der Pilger zurück, der den Hadsch ohne Sünde und ohne unanständiges Verhalten vollzieht?",c:["Wie am Tag, an dem seine Mutter ihn geboren hat","Reicher","Vom Fasten befreit","Mit dem Titel Hadschi, ohne weitere Belohnung"],b:0,e:"Er kehrt rein von seinen Sünden zurück.",s:['h:hajj_pardon']},
  {q:"Welcher Prophet erhielt den Befehl, die Menschen zur Pilgerfahrt aufzurufen?",c:["Ibrahim","Musa","Nuh","Yusuf"],b:0,e:"Allah befahl Ibrahim, die Menschen zum Hadsch aufzurufen.",s:['q:22:27']},
  {q:"Wie heißt der Weihezustand, in den der Pilger eintritt?",c:["Der Ihram","Das Wudu","Der I'tikaf","Das Tayammum"],b:0,e:"Die Männer tragen zwei ungenähte weiße Tücher.",s:['f:hajj']},
  {q:"Wie heißen die sieben Umrundungen der Kaaba?",c:["Der Tawaf","Der Sa'y","Die Rak'a","Der Dhikr"],b:0,e:"Der Tawaf besteht aus sieben Umrundungen, wobei die Kaaba links liegt.",s:['f:hajj']},
  {q:"Zwischen welchen beiden Hügeln geht der Pilger siebenmal hin und her?",c:["Safa und Marwa","Arafa und Mina","Uhud und Thaur","Hira und Thaur"],b:0,e:"Der Koran nennt Safa und Marwa unter den Kultzeichen Allahs.",s:['q:2:158']},
  {q:"In Erinnerung an welchen Propheten schlachten die Muslime am Opferfest (Eid al-Adha) ein Tier?",c:["Ibrahim","Isa","Musa","Dawud"],b:0,e:"Allah löste den Sohn Ibrahims durch ein großartiges Schlachtopfer aus.",s:['q:37:107']}
 ]},

/* ===================== KORAN ===================== */
'c-coran':{titre:"Der Koran, das Wort Allahs",
 texte:["Der Koran ist das Wort Allahs, das dem Propheten Muhammad ﷺ auf Arabisch durch den Engel Dschibril (Gabriel) offenbart wurde.",
  "Die erste Offenbarung fand in der Höhle Hira bei Mekka statt, als der Prophet ﷺ 40 Jahre alt war. Die ersten offenbarten Worte beginnen mit „Iqra'“: „Lies!“.",
  "Die Offenbarung dauerte etwa 23 Jahre. Der Koran hat 114 Suren; Allah hat sich verpflichtet, ihn zu bewahren."],
 retenir:"114 Suren, offenbart in 23 Jahren. Erstes Wort: „Iqra'“, „Lies!“.",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"Wie viele Suren hat der Koran?",c:["114","99","120","30"],b:0,e:"Der Koran hat 114 Suren.",s:['f:coran']},
  {q:"Welcher Engel hat dem Propheten Muhammad ﷺ den Koran überbracht?",c:["Dschibril (Gabriel)","Mika'il","Israfil","Malik"],b:0,e:"Der Engel Dschibril hat die Offenbarung überbracht.",s:['q:2:97']},
  {q:"In welcher Höhle empfing der Prophet ﷺ die erste Offenbarung des Korans?",c:["In der Höhle Hira","In der Höhle Thaur","In einer Höhle bei Medina","In einer Höhle bei Jerusalem"],b:0,e:"Die Höhle Hira liegt auf dem Dschabal an-Nur, bei Mekka.",s:['h:hira']},
  {q:"Was bedeutet „Iqra'“, das erste offenbarte Wort des Korans?",c:["Lies!","Bete!","Hör zu!","Faste!"],b:0,e:"Das ist der Anfang der Sure Al-Alaq (96).",s:['q:96:1']},
  {q:"Über wie viele Jahre ungefähr wurde der Koran offenbart?",c:["23 Jahre","1 Jahr","40 Jahre","10 Jahre"],b:0,e:"Etwa 13 Jahre in Mekka und 10 Jahre in Medina.",s:['h:vie']},
  {q:"In wie viele Teile (Dschuz') ist der Koran zum Lesen eingeteilt?",c:["30","114","7","12"],b:0,e:"Dreißig Teile: zum Beispiel einer pro Tag im Ramadan.",s:['f:coran']},
  {q:"In welcher Sprache wurde der Koran offenbart?",c:["Auf Arabisch","Auf Hebräisch","Auf Persisch","Auf Aramäisch"],b:0,e:"„Wir haben ihn als arabischen Koran herabgesandt.“",s:['q:12:2']},
  {q:"Wer sorgt laut dem Koran für die Bewahrung des Korans?",c:["Allah","Nur die Gelehrten","Die Kalifen","Niemand"],b:0,e:"„Wir haben die Ermahnung herabgesandt, und Wir werden sie bewahren.“",s:['q:15:9']},
  {q:"Wie alt war der Prophet ﷺ bei der ersten Offenbarung?",c:["40 Jahre","25 Jahre","63 Jahre","13 Jahre"],b:0,e:"Er begann mit 40 Jahren, die Offenbarung zu empfangen.",s:['h:vie']},
  {q:"Wie nennt man einen Vers des Korans auf Arabisch?",c:["Eine Aya","Eine Sure","Ein Dschuz'","Ein Hadith"],b:0,e:"Ein Vers heißt Aya; ein Kapitel heißt Sure.",s:['f:coran']}
 ]},
'c-sourates':{titre:"Die Suren",
 texte:["Der Koran besteht aus 114 Suren von sehr unterschiedlicher Länge. Jede beginnt mit der Basmala, außer der Sure At-Tauba.",
  "Die erste ist Al-Fatiha, „die Eröffnende“. Die längste ist Al-Baqara, „die Kuh“, mit 286 Versen. Die kürzeste ist Al-Kauthar, mit 3 Versen. Die letzte ist An-Nas, „die Menschen“.",
  "Die vor der Hidschra offenbarten Suren nennt man mekkanisch, die danach offenbarten medinensisch."],
 retenir:"Erste: Al-Fatiha. Längste: Al-Baqara. Kürzeste: Al-Kauthar. Letzte: An-Nas.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"Was ist die erste Sure des Korans?",c:["Al-Fatiha","Al-Baqara","An-Nas","Al-Alaq"],b:0,e:"Al-Fatiha eröffnet den Koran. Al-Alaq enthält die ersten offenbarten Verse, ist aber die Sure 96.",s:['q:1:1']},
  {q:"Was ist die längste Sure des Korans?",c:["Al-Baqara","Al-Fatiha","Al-Kauthar","Ya-Sin"],b:0,e:"Al-Baqara, die Sure 2, hat 286 Verse.",s:['f:coran']},
  {q:"Was ist die kürzeste Sure des Korans?",c:["Al-Kauthar","Al-Ikhlas","An-Nas","Al-Asr"],b:0,e:"Al-Kauthar, die Sure 108, hat 3 Verse.",s:['q:108:1']},
  {q:"Was ist die letzte Sure des Korans?",c:["An-Nas","Al-Falaq","Al-Ikhlas","Al-Fatiha"],b:0,e:"An-Nas, „die Menschen“, ist die Sure 114.",s:['q:114:1']},
  {q:"Welche Sure beginnt mit „Qul huwa Llahu aḥad“?",c:["Al-Ikhlas","An-Nas","Al-Falaq","Al-Kafirun"],b:0,e:"„Sag: Er ist Allah, ein Einziger.“",s:['q:112:1']},
  {q:"Welche Sure enthält den Vers „Dies ist das Buch, an dem es keinen Zweifel gibt“?",c:["Al-Baqara","Al-Fatiha","Maryam","Ya-Sin"],b:0,e:"Das ist der 2. Vers der Sure Al-Baqara.",s:['q:2:2']},
  {q:"Welche Sure trägt den Namen der Mutter von Isa (Jesus)?",c:["Maryam","Al Imran","An-Nisa'","Ta-Ha"],b:0,e:"Die Sure 19 trägt den Namen Maryam.",s:['q:19:16']},
  {q:"Welche ist die einzige Sure, die nicht mit „Bismi Llahi r-Raḥmani r-Raḥim“ beginnt?",c:["At-Tauba (Sure 9)","Al-Fatiha","An-Nas","Al-Baqara"],b:0,e:"At-Tauba ist die einzige der 114 Suren ohne Basmala am Anfang.",s:['f:tawba']},
  {q:"Wie nennt man die Formel „Bismi Llahi r-Raḥmani r-Raḥim“?",c:["Die Basmala","Die Schahada","Der Takbir","Die Talbiya"],b:0,e:"Sie bedeutet: „Im Namen Allahs, des Allerbarmers, des Barmherzigen“.",s:['q:1:1']},
  {q:"Wie nennt man die Suren, die in Mekka vor der Hidschra offenbart wurden?",c:["Die mekkanischen Suren","Die medinensischen Suren","Die langen Suren","Die Suren von Taif"],b:0,e:"Die nach der Hidschra offenbarten heißen medinensisch.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ikhlas und der Thronvers",
 texte:["Die Sure Al-Ikhlas (112) fasst den Glauben an die Einheit Allahs zusammen: Er ist einzig, Er hat nicht gezeugt und ist nicht gezeugt worden, und niemand ist Ihm gleich.",
  "Der Prophet ﷺ sagte, dass sie einem Drittel des Korans entspricht.",
  "Der Thronvers, Ayat al-Kursi (Sure 2, Vers 255), ist der größte Vers des Korans. Er beschreibt das Leben, das Wissen und die Macht Allahs."],
 retenir:"Al-Ikhlas entspricht einem Drittel des Korans. Ayat al-Kursi ist der größte Vers.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"Was bedeutet „Qul huwa Llahu aḥad“?",c:["Sag: Er ist Allah, ein Einziger","Im Namen Allahs","Allah ist der Größte","Gepriesen sei Allah"],b:0,e:"Das ist der erste Vers der Sure Al-Ikhlas.",s:['q:112:1']},
  {q:"Welchem Teil des Korans entspricht laut dem Hadith die Sure Al-Ikhlas?",c:["Einem Drittel","Der Hälfte","Einem Zehntel","Dem ganzen Koran"],b:0,e:"Der Prophet ﷺ sagte, dass sie einem Drittel des Korans entspricht.",s:['h:ikhlas']},
  {q:"Wie viele Verse hat die Sure Al-Ikhlas?",c:["4","7","3","5"],b:0,e:"Die Sure Al-Ikhlas hat 4 Verse.",s:['q:112:4']},
  {q:"Ist laut der Sure Al-Ikhlas jemand Allah gleich?",c:["Nein, niemand ist Ihm gleich","Ja, die Engel","Ja, die Propheten","Ja, die Dschinn"],b:0,e:"„Und niemand ist Ihm gleich.“",s:['q:112:4']},
  {q:"Was ist laut dem Hadith der größte Vers des Korans?",c:["Ayat al-Kursi, der Thronvers","Der erste Vers der Fatiha","Der letzte Vers des Korans","Der Lichtvers"],b:0,e:"Ubayy ibn Ka'b sagte es dem Propheten ﷺ, und er bestätigte es.",s:['h:kursi']},
  {q:"In welcher Sure steht Ayat al-Kursi?",c:["Al-Baqara, Vers 255","Al-Fatiha, Vers 1","Ya-Sin, Vers 1","Al-Ikhlas, Vers 2"],b:0,e:"Der Thronvers ist der 255. Vers der Sure Al-Baqara.",s:['q:2:255']},
  {q:"Wird Allah laut Ayat al-Kursi von Schlummer oder Schlaf ergriffen?",c:["Nein, weder Schlummer noch Schlaf ergreifen Ihn","Ja, nachts","Ja, manchmal","Nur vom Schlaf"],b:0,e:"Allah ist der Lebendige, der durch Sich Selbst Bestehende.",s:['q:2:255']},
  {q:"Was bedeutet „Allahu ṣ-ṣamad“ in der Sure Al-Ikhlas?",c:["Allah ist der, den alle brauchen und der niemanden braucht","Allah ist der Schöpfer des Himmels","Allah ist der Vergebende","Allah ist der Richter"],b:0,e:"As-Samad ist einer der Namen Allahs.",s:['q:112:2']},
  {q:"Was bedeutet der Name der Sure „Al-Ikhlas“?",c:["Der reine Monotheismus, die Aufrichtigkeit","Die Morgendämmerung","Der Sieg","Die Menschen"],b:0,e:"Sie reinigt den Glauben von jeder Beigesellung.",s:['f:ikhlas']},
  {q:"Was gewährt Allah laut Ayat al-Kursi Seinen Geschöpfen von Seinem Wissen?",c:["Nur das, was Er will","Sein ganzes Wissen","Gar nichts","Die Hälfte"],b:0,e:"„Und sie umfassen nichts von Seinem Wissen, außer was Er will.“",s:['q:2:255']}
 ]},

/* ===================== PROPHETEN ===================== */
'pr-adam':{titre:"Adam und Nuh",
 texte:["Adam ist der erste Mensch und der erste Prophet. Allah lehrte ihn die Namen aller Dinge und befahl dann den Engeln, sich vor ihm niederzuwerfen. Iblis weigerte sich aus Hochmut.",
  "Nuh (Noah) rief sein Volk 950 Jahre lang dazu auf, Allah allein anzubeten. Nur wenige folgten ihm, nicht einmal sein eigener Sohn.",
  "Auf Allahs Befehl baute Nuh die Arche, die ihn zusammen mit den Gläubigen und Tierpaaren vor der Sintflut rettete."],
 retenir:"Adam, der erste Mensch. Nuh, 950 Jahre Verkündigung, und die Arche.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"Wer ist der erste Prophet der Menschheit?",c:["Adam","Nuh (Noah)","Ibrahim (Abraham)","Musa (Mose)"],b:0,e:"Adam ist der erste Mensch und der erste Prophet.",s:['q:2:31']},
  {q:"Was hat Allah Adam gelehrt?",c:["Die Namen aller Dinge","Den Koran auswendig","Nur die Sprache der Engel","Nur die Namen der Propheten"],b:0,e:"„Und Er lehrte Adam alle Namen.“",s:['q:2:31']},
  {q:"Wer weigerte sich, sich vor Adam niederzuwerfen?",c:["Iblis","Dschibril","Mika'il","Alle Engel"],b:0,e:"Die Engel warfen sich nieder, außer Iblis.",s:['q:2:34']},
  {q:"Warum weigerte sich Iblis, sich vor Adam niederzuwerfen?",c:["Aus Hochmut","Aus Vergesslichkeit","Aus Angst","Weil er den Befehl nicht gehört hatte"],b:0,e:"Er weigerte sich, war hochmütig und gehörte zu den Ungläubigen.",s:['q:2:34']},
  {q:"Wo lebten Adam und seine Frau, bevor sie auf die Erde hinabstiegen?",c:["Im Paradies","In Mekka","In Ägypten","In Jerusalem"],b:0,e:"„Bewohne du und deine Gattin das Paradies.“",s:['q:2:35']},
  {q:"Welcher Prophet baute auf Allahs Befehl die Arche?",c:["Nuh (Noah)","Yunus (Jona)","Sulaiman (Salomo)","Isa (Jesus)"],b:0,e:"Nuh baute die Arche unter Allahs Augen und nach Seiner Offenbarung.",s:['q:11:37']},
  {q:"Wie lange blieb Nuh laut dem Koran unter seinem Volk?",c:["950 Jahre","40 Jahre","100 Jahre","313 Jahre"],b:0,e:"„Tausend Jahre weniger fünfzig Jahre.“",s:['q:29:14']},
  {q:"Wer wurde in der Arche Nuhs gerettet?",c:["Nuh, die Gläubigen und Tierpaare","Sein ganzes Volk","Nur die Tiere","Niemand"],b:0,e:"Allah befahl, ein Paar von jeder Art, seine Familie und die Gläubigen hineinzubringen.",s:['q:11:40']},
  {q:"Ist der Sohn Nuhs in die Arche gestiegen?",c:["Nein, er weigerte sich und ertrank","Ja, als Erster","Ja, am Ende","Er hatte keinen Sohn"],b:0,e:"Er meinte, auf einem Berg Zuflucht zu finden, aber die Wellen rissen ihn fort.",s:['q:11:43']},
  {q:"Wie heißt die Frau Adams nach der islamischen Überlieferung?",c:["Hawwa' (Eva)","Maryam","Asiya","Hadschar"],b:0,e:"Der Koran erwähnt sie, ohne sie zu nennen; ihr Name stammt aus der Sunna.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, der Freund Allahs",
 texte:["Ibrahim (Abraham) weigerte sich, die Götzen seines Volkes anzubeten. Man warf ihn in ein großes Feuer, doch Allah befahl dem Feuer, für ihn Kühle und Frieden zu sein.",
  "Allah nahm ihn zum engen Freund (Khalil). Er ist der Vater zweier Propheten: Isma'il und Ishaq.",
  "Mit seinem Sohn Isma'il errichtete er die Grundmauern der Kaaba. Das Opfer am Opferfest (Eid al-Adha) erinnert an seinen Gehorsam gegenüber Allah."],
 retenir:"Ibrahim, der Freund Allahs, aus dem Feuer gerettet, Erbauer der Kaaba mit Isma'il.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"Welcher Prophet errichtete mit seinem Sohn Isma'il die Grundmauern der Kaaba?",c:["Ibrahim (Abraham)","Musa (Mose)","Dawud (David)","Adam"],b:0,e:"Ibrahim und sein Sohn Isma'il errichteten die Grundmauern der Kaaba.",s:['q:2:127']},
  {q:"Was geschah mit Ibrahim, als sein Volk ihn ins Feuer warf?",c:["Allah machte das Feuer für ihn kühl und ungefährlich","Er floh","Er wurde verletzt","Er wurde durch Regen gerettet"],b:0,e:"„O Feuer, sei Kühle und Unversehrtheit für Ibrahim.“",s:['q:21:69']},
  {q:"Welchen Titel gibt der Koran dem Propheten Ibrahim?",c:["Der enge Freund Allahs (Khalil)","Das Siegel der Propheten","Derjenige, mit dem Allah gesprochen hat","Der Geist Allahs"],b:0,e:"„Und Allah nahm Ibrahim zum engen Freund.“",s:['q:4:125']},
  {q:"Wer sind die beiden Söhne Ibrahims, die Propheten waren?",c:["Isma'il und Ishaq","Musa und Harun","Dawud und Sulaiman","Yahya und Isa"],b:0,e:"Ibrahim dankte Allah, dass Er ihm im hohen Alter Isma'il und Ishaq geschenkt hatte.",s:['q:14:39']},
  {q:"Was tat das Volk Ibrahims, was er ablehnte?",c:["Statuen anbeten","Fasten","Spenden geben","Pilgern"],b:0,e:"Er fragte sie: „Was sind das für Bildwerke, an denen ihr hängt?“",s:['q:21:52']},
  {q:"Womit löste Allah den Sohn Ibrahims im Moment des Opfers aus?",c:["Mit einem großartigen Schlachtopfer (einem Opfertier)","Mit einer Spende aus Gold","Mit dem Fasten seines Vaters","Mit einem Nachtgebet"],b:0,e:"Die Überlieferung präzisiert, dass es ein Widder war.",s:['q:37:107']},
  {q:"Welches Fest erinnert an den Gehorsam Ibrahims gegenüber Allah?",c:["Das Opferfest (Eid al-Adha)","Das Ramadanfest (Eid al-Fitr)","Der 1. Muharram","Der Maulid"],b:0,e:"Das Opfer am Opferfest erinnert an seine Prüfung.",s:['q:37:107']},
  {q:"Wie wird Ibrahim im Koran beschrieben?",c:["Als monotheistischer Gläubiger (Hanif), weder Jude noch Christ","Als König von Babylon","Als Engel","Als Dichter"],b:0,e:"Er war Allah völlig ergeben.",s:['q:3:67']},
  {q:"Welcher Sohn half Ibrahim, die Grundmauern der Kaaba zu errichten?",c:["Isma'il","Ishaq","Ya'qub","Yusuf"],b:0,e:"Ibrahim und Isma'il errichteten gemeinsam die Grundmauern des Hauses.",s:['q:2:127']},
  {q:"Welches ist laut dem Koran das erste Haus der Anbetung, das für die Menschen errichtet wurde?",c:["Das in Bakka (Mekka)","Das in Jerusalem","Das in Medina","Das in Taif"],b:0,e:"Bakka ist ein Name Mekkas.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yunus, Yusuf und Sulaiman",
 texte:["Yunus (Jona) wurde von einem großen Fisch verschluckt. In der Finsternis rief er Allah an, der ihn aus der Bedrängnis rettete.",
  "Die Geschichte von Yusuf (Josef), der von seinen Brüdern verraten wurde und später Minister in Ägypten wurde, füllt die ganze Sure 12: „die schönste Erzählung“.",
  "Sulaiman (Salomo), der Sohn Dawuds, erhielt ein riesiges Königreich und verstand die Sprache der Vögel und der Ameisen."],
 retenir:"Yunus und der Fisch. Yusuf, Sure 12. Sulaiman und die Sprache der Tiere.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"Welcher Prophet wurde von einem großen Fisch verschluckt?",c:["Yunus (Jona)","Yusuf (Josef)","Ayyub (Hiob)","Lut (Lot)"],b:0,e:"Yunus wurde von dem Fisch verschluckt, dann rettete ihn Allah.",s:['q:37:142']},
  {q:"Welche Sure des Korans erzählt die ganze Geschichte des Propheten Yusuf (Josef)?",c:["Die Sure 12, Yusuf","Die Sure 1, Al-Fatiha","Die Sure 36, Ya-Sin","Die Sure 112, Al-Ikhlas"],b:0,e:"Die Sure 12 trägt seinen Namen.",s:['q:12:3']},
  {q:"Welcher Prophet verstand die Sprache der Ameisen?",c:["Sulaiman (Salomo)","Salih","Hud","Zakariyya"],b:0,e:"Sulaiman hörte eine Ameise die anderen warnen und lächelte über ihre Worte.",s:['q:27:18']},
  {q:"Welches Bittgebet sprach Yunus im Bauch des Fisches?",c:["„La ilaha illa anta, subḥanaka, inni kuntu mina ẓ-ẓalimin“","„Bismi Llah“","„Allahu akbar“","„Rabbana atina“"],b:0,e:"„Es gibt keinen Gott außer Dir! Gepriesen seist Du! Ich gehörte wahrlich zu den Ungerechten.“",s:['q:21:87']},
  {q:"Wie antwortete Allah auf das Bittgebet von Yunus?",c:["Er rettete ihn aus der Bedrängnis","Er ließ ihn im Fisch","Er ließ ihn drei Jahre im Fisch","Er antwortete nicht"],b:0,e:"„Da erhörten Wir ihn und retteten ihn aus der Bedrängnis.“",s:['q:21:88']},
  {q:"Wie viele Sterne sah Yusuf in seinem Kindheitstraum sich vor ihm niederwerfen?",c:["Elf, mit der Sonne und dem Mond","Sieben","Zwölf","Nur einen"],b:0,e:"Elf Sterne, die Sonne und der Mond.",s:['q:12:4']},
  {q:"Wer warf Yusuf auf den Grund eines Brunnens?",c:["Seine Brüder","Der Pharao","Händler","Sein Vater"],b:0,e:"Seine eifersüchtigen Brüder beschlossen, ihn auf den Grund des Brunnens zu werfen.",s:['q:12:15']},
  {q:"Wie nennt der Koran die Geschichte von Yusuf?",c:["Die schönste Erzählung","Die Erzählung vom Feuer","Das Buch der Weisheit","Die Erzählung von der Arche"],b:0,e:"„Wir erzählen dir die schönste Erzählung.“",s:['q:12:3']},
  {q:"Welcher Prophet erhielt das Wissen um die Sprache der Vögel?",c:["Sulaiman","Yunus","Nuh","Hud"],b:0,e:"„Uns ist die Sprache der Vögel gelehrt worden“, sagte Sulaiman.",s:['q:27:16']},
  {q:"Wer war der Vater Sulaimans, ebenfalls Prophet und König?",c:["Dawud (David)","Ibrahim","Ya'qub","Musa"],b:0,e:"„Und Sulaiman beerbte Dawud.“",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Musa, mit dem Allah gesprochen hat",
 texte:["Musa (Mose) wurde in Ägypten geboren, zu der Zeit, als der Pharao die Banu Isra'il verfolgte. Auf Allahs Eingebung hin setzte seine Mutter ihn auf dem Fluss aus, und die Familie des Pharaos nahm ihn auf.",
  "Allah sprach direkt zu ihm und sandte ihn mit seinem Bruder Harun und mit Wundern zum Pharao, wie seinem Stab, der zu einer Schlange wurde.",
  "Allah spaltete das Meer, um Musa und sein Volk zu retten, und der Pharao ertrank. Musa ist der Prophet, der im Koran am häufigsten genannt wird."],
 retenir:"Musa, aus dem Wasser gerettet, Kalim Allah, das gespaltene Meer.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"In welchem Land wurde der Prophet Musa (Mose) geboren?",c:["In Ägypten","In Arabien","Im Irak","Im Jemen"],b:0,e:"Er wurde in Ägypten geboren, unter der Herrschaft des Pharaos.",s:['q:28:7']},
  {q:"Was tat die Mutter von Musa, um ihn vor dem Pharao zu schützen?",c:["Sie setzte ihn auf dem Fluss aus","Sie versteckte ihn in einer Höhle","Sie ging in die Wüste","Sie vertraute ihn einem Hirten an"],b:0,e:"Allah gab ihr ein, ihn ohne Furcht in den Fluss zu legen.",s:['q:28:7']},
  {q:"Wer nahm das Baby Musa aus dem Fluss auf?",c:["Die Familie des Pharaos","Fischer","Ibrahim","Ein König aus dem Jemen"],b:0,e:"Die Leute des Pharaos nahmen ihn auf.",s:['q:28:8']},
  {q:"Welcher Prophet wird „Kalim Allah“ genannt, derjenige, mit dem Allah direkt gesprochen hat?",c:["Musa","Ibrahim","Isa","Nuh"],b:0,e:"„Und mit Musa hat Allah wirklich gesprochen.“",s:['q:4:164']},
  {q:"Was wurde aus dem Stab von Musa, als er ihn auf den Boden warf?",c:["Eine Schlange","Ein Baum","Eine Taube","Ein Schwert"],b:0,e:"„Er warf ihn hin, und da war er eine Schlange, die sich schnell bewegte.“",s:['q:20:20']},
  {q:"Was geschah, als Musa mit seinem Stab auf das Meer schlug?",c:["Es spaltete sich in zwei Teile","Es wurde zu Sand","Es trocknete auf einen Schlag aus","Nichts"],b:0,e:"Jeder Teil war wie ein gewaltiger Berg.",s:['q:26:63']},
  {q:"Was geschah mit dem Pharao und seinem Heer, die Musa verfolgten?",c:["Sie ertranken im Meer","Sie bekehrten sich","Sie kehrten nach Ägypten zurück","Sie zogen ebenfalls hindurch"],b:0,e:"Allah rettete Musa und die mit ihm waren und ließ die anderen ertrinken.",s:['q:26:66']},
  {q:"Wie hieß der Bruder von Musa, der ihm bei seiner Mission half?",c:["Harun (Aaron)","Yusuf","Ishaq","Yahya"],b:0,e:"Musa bat Allah, ihm seinen Bruder Harun als Helfer zu geben.",s:['q:20:30']},
  {q:"Zu welchem König sandte Allah Musa?",c:["Zum Pharao","Zu Nimrod","Zum König von Saba","Zu Goliath"],b:0,e:"„Geh zum Pharao, denn er überschreitet das Maß.“",s:['q:20:24']},
  {q:"Welcher Prophet wird im Koran am häufigsten mit Namen genannt?",c:["Musa","Muhammad ﷺ","Ibrahim","Nuh"],b:0,e:"Musa wird im Koran mehr als 130-mal genannt.",s:['f:musa']}
 ]},
'pr-isa':{titre:"Isa und Maryam",
 texte:["Maryam (Maria), die Mutter von Isa, ist die einzige Frau, die im Koran mit Namen genannt wird. Allah hat sie vor den Frauen der Welten auserwählt, und eine Sure trägt ihren Namen.",
  "Isa (Jesus) wurde ohne Vater geboren, durch den Willen Allahs, so wie Adam ohne Vater und Mutter erschaffen wurde. Als Baby sprach er in der Wiege.",
  "Für die Muslime ist Isa ein großer Prophet und Gesandter Allahs, der Messias, dem das Indschil (Evangelium) offenbart wurde."],
 retenir:"Maryam, auserwählt unter den Frauen. Isa, ohne Vater geboren, Prophet und Messias.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"Welche ist die einzige Frau, die im Koran mit Namen genannt wird?",c:["Maryam","Khadidscha","Asiya","Hawwa'"],b:0,e:"Maryam ist die einzige Frau, die mit Namen genannt wird; die Sure 19 trägt ihren Namen.",s:['f:maryam']},
  {q:"Was sagt der Koran über Maryam?",c:["Allah hat sie vor den Frauen der Welten auserwählt","Sie war Königin von Ägypten","Sie war Prophetin von Medina","Der Koran spricht nicht über sie"],b:0,e:"Die Engel verkündeten ihr, dass Allah sie auserwählt und gereinigt hatte.",s:['q:3:42']},
  {q:"Wie wurde der Prophet Isa (Jesus) geboren?",c:["Ohne Vater, durch den Willen Allahs","Wie alle anderen","Im Palast des Pharaos","In Mekka"],b:0,e:"Allah sagt „Sei!“, und er war.",s:['q:3:59']},
  {q:"Mit wessen Erschaffung vergleicht der Koran die Erschaffung von Isa?",c:["Mit der von Adam","Mit der der Engel","Mit der von Nuh","Mit der von Iblis"],b:0,e:"Adam wurde ohne Vater und Mutter erschaffen; Isa ohne Vater.",s:['q:3:59']},
  {q:"Welches Wunder vollbrachte Isa, als er ein Baby war?",c:["Er sprach in der Wiege","Er ging auf dem Wasser","Er ließ das Wasser von Zamzam hervorsprudeln","Er durchquerte das Meer"],b:0,e:"Er verteidigte seine Mutter, indem er aus der Wiege sprach.",s:['q:19:30']},
  {q:"Was waren laut dem Koran die ersten Worte des Babys Isa?",c:["„Ich bin der Diener Allahs“","„Ich bin König“","„Ich bin ein Engel“","„Ich bin der Sohn Zakariyyas“"],b:0,e:"„Ich bin wahrlich Allahs Diener. Er hat mir die Schrift gegeben und mich zum Propheten gemacht.“",s:['q:19:30']},
  {q:"Welchen Titel gibt der Koran Isa?",c:["Al-Masih, der Messias","Der Khalil","Das Siegel der Propheten","Kalim Allah"],b:0,e:"Die Engel verkünden Maryam: „Sein Name ist al-Masih, Isa, Sohn der Maryam.“",s:['q:3:45']},
  {q:"Welches Buch hat Allah dem Propheten Isa offenbart?",c:["Das Indschil (Evangelium)","Die Taura (Tora)","Den Zabur (Psalmen)","Den Koran"],b:0,e:"„Wir gaben ihm das Evangelium, in dem Rechtleitung und Licht ist.“",s:['q:5:46']},
  {q:"Wer ist Isa für die Muslime?",c:["Ein Prophet und Gesandter Allahs","Eine Gottheit","Ein Engel","Ein König von Jerusalem"],b:0,e:"Er stellt sich selbst als Diener Allahs und Prophet vor.",s:['q:19:30']},
  {q:"Wer wurde zu Maryam gesandt, um ihr die Geburt von Isa zu verkünden?",c:["Der Geist Allahs, der Engel Dschibril","Zakariyya","Yahya","Der Engel Mika'il"],b:0,e:"Die Gelehrten erklären, dass „Unser Geist“ den Engel Dschibril bezeichnet.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, der letzte Prophet",
 texte:["Muhammad ﷺ wurde um 570 in Mekka geboren, im „Jahr des Elefanten“, im Stamm der Quraisch. Sein Vater starb vor seiner Geburt, seine Mutter Amina verlor er mit 6 Jahren; er wuchs bei seinem Großvater und dann bei seinem Onkel Abu Talib auf.",
  "Er war für seine Ehrlichkeit bekannt, man nannte ihn al-Amin, „der Vertrauenswürdige“. Mit 40 Jahren empfing er die erste Offenbarung.",
  "Er starb 632 in Medina im Alter von 63 Jahren. Allah hat ihn als Barmherzigkeit für die Welten gesandt."],
 retenir:"Geboren um 570 in Mekka, Offenbarung mit 40, gestorben mit 63 in Medina.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"In welcher Stadt wurde der Prophet Muhammad ﷺ geboren?",c:["Mekka","Medina","Jerusalem","Taif"],b:0,e:"Er wurde um 570 in Mekka geboren.",s:['f:sira']},
  {q:"Wie nennt man das Geburtsjahr des Propheten ﷺ?",c:["Das Jahr des Elefanten","Das Jahr der Hidschra","Das Jahr der Trauer","Das Jahr des Sieges"],b:0,e:"Das Jahr, in dem ein Heer mit Elefanten Mekka angriff (Sure 105).",s:['q:105:1']},
  {q:"Wie hieß die Mutter des Propheten ﷺ?",c:["Amina","Khadidscha","Halima","Fatima"],b:0,e:"Amina bint Wahb starb, als er 6 Jahre alt war.",s:['f:sira']},
  {q:"Welcher Onkel zog den Propheten ﷺ auf und beschützte ihn?",c:["Abu Talib","Abu Lahab","Hamza","Al-Abbas"],b:0,e:"Nach dem Tod seines Großvaters nahm ihn sein Onkel Abu Talib auf.",s:['f:sira']},
  {q:"Welchen Beinamen gaben die Mekkaner dem Propheten ﷺ vor der Offenbarung?",c:["Al-Amin, der Vertrauenswürdige","Al-Faruq","As-Siddiq","Saifullah"],b:0,e:"Er war bei allen für seine Ehrlichkeit bekannt.",s:['f:sira']},
  {q:"In welchem Alter ist der Prophet ﷺ gestorben?",c:["Mit 63 Jahren","Mit 40 Jahren","Mit 70 Jahren","Mit 53 Jahren"],b:0,e:"Ibn Abbas berichtet, dass er mit 63 Jahren starb.",s:['h:vie']},
  {q:"In welcher Stadt ist der Prophet ﷺ gestorben?",c:["Medina","Mekka","Jerusalem","Damaskus"],b:0,e:"Er starb 632 in Medina und ist dort begraben.",s:['f:sira']},
  {q:"Warum hat Allah laut dem Koran Muhammad ﷺ gesandt?",c:["Als Barmherzigkeit für die Welten","Um König zu sein","Um die Menschen zu bestrafen","Nur für die Araber"],b:0,e:"„Wir haben dich nur als Barmherzigkeit für die Welten gesandt.“",s:['q:21:107']},
  {q:"Was sagt der Koran über den Charakter des Propheten ﷺ?",c:["Er ist von großartiger Wesensart","Er ist streng","Er ist gleichgültig","Der Koran spricht nicht darüber"],b:0,e:"„Und du bist wahrlich von großartiger Wesensart.“",s:['q:68:4']},
  {q:"Zu welchem Stamm gehörte der Prophet ﷺ?",c:["Quraisch","Aus","Khazradsch","Thaqif"],b:0,e:"Quraisch, der große Stamm von Mekka.",s:['f:sira']}
 ]},
'pr-livres':{titre:"Die offenbarten Bücher und der Glaube",
 texte:["Allah hat einigen Propheten Bücher offenbart: die Taura (Tora) an Musa, den Zabur (Psalmen) an Dawud, das Indschil (Evangelium) an Isa und den Koran an Muhammad ﷺ.",
  "Der Koran nennt 25 Propheten, doch Allah hat noch viele andere gesandt. Der Gläubige glaubt an alle, ohne Unterschied.",
  "Der Glaube (Iman) beruht auf sechs Säulen: an Allah glauben, an Seine Engel, an Seine Bücher, an Seine Gesandten, an den Jüngsten Tag und an die Vorherbestimmung."],
 retenir:"Taura, Zabur, Indschil, Koran. Sechs Säulen des Glaubens.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"Welches Buch hat Allah dem Propheten Musa (Mose) offenbart?",c:["Die Taura (Tora)","Den Zabur (Psalmen)","Das Indschil (Evangelium)","Den Koran"],b:0,e:"Die Taura an Musa, der Zabur an Dawud, das Indschil an Isa, der Koran an Muhammad ﷺ.",s:['q:5:44']},
  {q:"Wie viele Propheten werden im Koran mit Namen genannt?",c:["25","12","40","313"],b:0,e:"25 Propheten werden genannt; 18 von ihnen werden zusammen in der Sure Al-An'am erwähnt.",s:['f:prophetes25']},
  {q:"Welchen Propheten nennt der Koran „das Siegel der Propheten“, also den letzten?",c:["Muhammad ﷺ","Isa (Jesus)","Musa (Mose)","Ibrahim (Abraham)"],b:0,e:"Muhammad ﷺ ist der letzte der Propheten.",s:['q:33:40']},
  {q:"Welches Buch wurde dem Propheten Dawud (David) offenbart?",c:["Der Zabur (Psalmen)","Die Taura","Das Indschil","Die Blätter Ibrahims"],b:0,e:"„Und Wir gaben Dawud den Zabur.“",s:['q:4:163']},
  {q:"Gehört der Glaube an die offenbarten Bücher zum Glauben des Muslims?",c:["Ja, er ist eine Säule des Glaubens","Nein, nur an den Koran","Nein, er ist freiwillig","Nur im Ramadan"],b:0,e:"Die Gläubigen glauben an Allah, Seine Engel, Seine Bücher und Seine Gesandten.",s:['q:2:285']},
  {q:"Wie viele Säulen hat der Glaube (Iman)?",c:["6","5","4","10"],b:0,e:"Allah, die Engel, die Bücher, die Gesandten, der Jüngste Tag und die Vorherbestimmung.",s:['h:jibril']},
  {q:"Welches dieser Elemente ist KEINE Säule des Glaubens (Iman)?",c:["Das Fasten im Ramadan","Der Glaube an die Engel","Der Glaube an den Jüngsten Tag","Der Glaube an die Bücher"],b:0,e:"Das Fasten ist eine Säule des Islam (der Praxis), nicht des Glaubens (der Überzeugung).",s:['h:jibril']},
  {q:"Welches Buch zu bewahren, hat Allah Sich verpflichtet?",c:["Den Koran","Die Taura","Den Zabur","Alle Bücher der Könige"],b:0,e:"„Und Wir werden sie wahrlich bewahren.“",s:['q:15:9']},
  {q:"Erzählt der Koran die Geschichte aller Gesandten, die Allah geschickt hat?",c:["Nein, nur von einigen","Ja, von allen","Er erzählt von keinem","Nur von den arabischen"],b:0,e:"„Es gibt Gesandte, von denen Wir dir erzählt haben, und Gesandte, von denen Wir dir nicht erzählt haben.“",s:['q:4:164']},
  {q:"Machen die Gläubigen laut dem Koran in ihrem Glauben einen Unterschied zwischen den Gesandten?",c:["Nein, sie glauben an alle","Ja, sie glauben nur an einen","Ja, sie lehnen die früheren ab","Sie glauben an keinen"],b:0,e:"„Wir machen keinen Unterschied zwischen Seinen Gesandten.“",s:['q:2:285']}
 ]},

/* ===================== GESCHICHTE & GEFÄHRTEN ===================== */
'h-khadija':{titre:"Khadidscha und die Anfänge des Islam",
 texte:["Khadidscha war eine angesehene Händlerin in Mekka. Sie heiratete den Propheten ﷺ, der damals 25 Jahre alt war.",
  "Nach der ersten Offenbarung war sie es, die ihn tröstete und als Erste an ihn glaubte. Sie brachte ihn zu ihrem Cousin Waraqa ibn Naufal.",
  "Zu den ersten Muslimen gehörten Abu Bakr, Ali, Zaid ibn Haritha und Bilal. 13 Jahre lang wurden die Muslime in Mekka verfolgt; Sumayya war die erste Märtyrerin."],
 retenir:"Khadidscha, die Erste, die glaubte. 13 Jahre Verkündigung in Mekka.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"Wer war die erste Ehefrau des Propheten ﷺ?",c:["Khadidscha","Aischa","Hafsa","Zainab"],b:0,e:"Khadidscha war der erste Mensch, der an seine Botschaft glaubte.",s:['h:hira']},
  {q:"Wer tröstete den Propheten ﷺ direkt nach der ersten Offenbarung in der Höhle Hira?",c:["Khadidscha","Abu Bakr","Ali","Bilal"],b:0,e:"Er kehrte zu Khadidscha zurück, die ihn beruhigte.",s:['h:hira']},
  {q:"Welcher Tätigkeit ging Khadidscha in Mekka nach?",c:["Dem Handel","Der Medizin","Der Dichtung","Der Kamelzucht"],b:0,e:"Sie war eine reiche, angesehene Händlerin.",s:['f:debuts']},
  {q:"Wie alt war der Prophet ﷺ, als er Khadidscha heiratete?",c:["25 Jahre","40 Jahre","18 Jahre","30 Jahre"],b:0,e:"Er war 25 Jahre alt.",s:['f:debuts']},
  {q:"Zu wem brachte Khadidscha den Propheten ﷺ nach der ersten Offenbarung?",c:["Zu ihrem Cousin Waraqa ibn Naufal","Zu Abu Talib","Zu Abu Bakr","Zum König von Abessinien"],b:0,e:"Waraqa kannte die alten Schriften.",s:['h:hira']},
  {q:"Welcher Junge gehörte zu den Ersten, die den Islam annahmen?",c:["Ali ibn Abi Talib","Umar","Khalid","Mu'awiya"],b:0,e:"Ali, der Cousin des Propheten ﷺ, war noch ein Kind.",s:['f:debuts']},
  {q:"Wie viele Jahre ungefähr verkündete der Prophet ﷺ in Mekka vor der Hidschra?",c:["13 Jahre","3 Jahre","23 Jahre","40 Jahre"],b:0,e:"Ibn Abbas berichtet, dass er nach der Offenbarung 13 Jahre in Mekka blieb.",s:['h:vie']},
  {q:"Welcher Freund des Propheten ﷺ war der erste erwachsene Mann, der den Islam annahm?",c:["Abu Bakr","Umar","Uthman","Hamza"],b:0,e:"Abu Bakr glaubte ohne Zögern an ihn.",s:['f:debuts']},
  {q:"Welcher ehemalige Sklave, der für seinen Glauben verfolgt wurde, wurde der erste Muezzin des Islam?",c:["Bilal ibn Rabah","Zaid ibn Haritha","Salman","Anas"],b:0,e:"Seine Stimme trug weit: Der Prophet ﷺ vertraute ihm den Adhan an.",s:['h:adhan']},
  {q:"Wie hieß die erste Märtyrerin des Islam?",c:["Sumayya","Khadidscha","Fatima","Asma'"],b:0,e:"Sumayya, die Mutter von Ammar, wurde in Mekka wegen ihres Glaubens getötet.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"Die Hidschra",
 texte:["Im Jahr 622 verließ der Prophet ﷺ angesichts der Verfolgungen Mekka und ging nach Medina, das damals Yathrib hieß: Das ist die Hidschra. Sie markiert das Jahr 1 des islamischen Kalenders.",
  "Während der Reise versteckte er sich mit seinem Freund Abu Bakr in der Höhle Thaur.",
  "In Medina wurde er von den Ansar (den „Helfern“) empfangen, die ihren Besitz mit den Muhadschirun (den „Auswanderern“) teilten. Dort baute er seine Moschee."],
 retenir:"622: die Hidschra, Jahr 1. Muhadschirun und Ansar.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"Was ist die Hidschra?",c:["Die Auswanderung des Propheten ﷺ von Mekka nach Medina","Die erste Pilgerfahrt","Eine Schlacht","Die Geburt des Propheten ﷺ"],b:0,e:"Sie markiert das Jahr 1 des islamischen Kalenders.",s:['f:hegire']},
  {q:"Welcher Gefährte begleitete den Propheten ﷺ während der Hidschra in der Höhle?",c:["Abu Bakr as-Siddiq","Umar ibn al-Khattab","Ali ibn Abi Talib","Bilal"],b:0,e:"Abu Bakr war „der Zweite von zweien“ in der Höhle.",s:['q:9:40']},
  {q:"In welchem Jahr fand die Hidschra statt?",c:["622","570","632","610"],b:0,e:"Die Hidschra fand im Jahr 622 christlicher Zeitrechnung statt.",s:['f:hegire']},
  {q:"In welcher Höhle versteckte sich der Prophet ﷺ während der Hidschra?",c:["In der Höhle Thaur","In der Höhle Hira","In der Höhle von Uhud","In der Höhle von Badr"],b:0,e:"Thaur liegt südlich von Mekka; Hira, der Ort der ersten Offenbarung, im Norden.",s:['f:hegire']},
  {q:"Wie lautete der frühere Name von Medina?",c:["Yathrib","Bakka","Taif","Quba'"],b:0,e:"Der Koran nennt diesen Namen: „O Leute von Yathrib“.",s:['q:33:13']},
  {q:"Wie nennt man die Bewohner Medinas, die die Muslime aufnahmen?",c:["Die Ansar","Die Muhadschirun","Die Quraisch","Die Banu Isra'il"],b:0,e:"Ansar bedeutet „die Helfer“.",s:['q:9:100']},
  {q:"Wie nennt man die Muslime, die von Mekka nach Medina auswanderten?",c:["Die Muhadschirun","Die Ansar","Die Khawaridsch","Die Beduinen"],b:0,e:"Muhadschirun bedeutet „die Auswanderer“.",s:['q:9:100']},
  {q:"Was sagte der Prophet ﷺ laut dem Koran in der Höhle zu Abu Bakr?",c:["„Sei nicht traurig, Allah ist mit uns“","„Lass uns schnell fliehen“","„Lass uns nach Mekka zurückkehren“","„Lass uns gegen sie kämpfen“"],b:0,e:"Das ist Vers 40 der Sure At-Tauba.",s:['q:9:40']},
  {q:"Unter welchem Kalifen wurde der Hidschri-Kalender eingeführt?",c:["Umar","Abu Bakr","Uthman","Ali"],b:0,e:"Umar machte die Hidschra zum Ausgangspunkt des Kalenders.",s:['f:hegire']},
  {q:"Was baute der Prophet ﷺ bei seiner Ankunft in Medina?",c:["Seine Moschee","Einen Palast","Eine Festung","Einen Markt"],b:0,e:"Die Moschee des Propheten (al-Masdschid an-Nabawi).",s:['f:hegire']}
 ]},
'h-badr':{titre:"Die Schlacht von Badr",
 texte:["Am 17. Ramadan im Jahr 2 nach der Hidschra (624) traten die Muslime bei den Brunnen von Badr gegen das Heer der Quraisch an.",
  "Sie waren etwa 313, gegenüber fast 1000 Kämpfern. Allah unterstützte sie mit Engeln, und sie errangen den Sieg.",
  "Der Koran nennt diesen Tag „den Tag der Unterscheidung“ (Yaum al-Furqan), an dem die Wahrheit vom Irrtum unterschieden wurde."],
 retenir:"17. Ramadan im Jahr 2: Badr, 313 gegen 1000, der Tag der Unterscheidung.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"In welchem Monat fand die Schlacht von Badr statt?",c:["Ramadan","Muharram","Dhul-Hiddscha","Radschab"],b:0,e:"Am 17. Ramadan im Jahr 2 nach der Hidschra.",s:['f:badr']},
  {q:"In welchem Jahr nach der Hidschra fand die Schlacht von Badr statt?",c:["Im Jahr 2","Im Jahr 8","Im Jahr 10","Im Jahr 1"],b:0,e:"Im Jahr 624 christlicher Zeitrechnung.",s:['f:badr']},
  {q:"Wie viele Muslime ungefähr kämpften bei Badr?",c:["Etwa 313","Etwa 3000","Etwa 10.000","Etwa 50"],b:0,e:"Sie waren etwa 313.",s:['f:badr']},
  {q:"Wie viele Kämpfer ungefähr zählte das Heer der Quraisch bei Badr?",c:["Fast 1000","Fast 100","Fast 10.000","Fast 300"],b:0,e:"Die Mekkaner waren dreimal so zahlreich.",s:['f:badr']},
  {q:"Wie hat Allah laut dem Koran die Muslime bei Badr unterstützt?",c:["Mit Engeln","Mit einem Sandsturm","Mit Verstärkung aus Persien","Nur mit Regen"],b:0,e:"Allah erhörte ihren Ruf und sandte Engel.",s:['q:8:9']},
  {q:"Wie viele Engel versprach Allah laut der Sure Al-Anfal bei Badr als Verstärkung zu senden?",c:["Tausend","Hundert","Zehn","Dreihundert"],b:0,e:"„Ich werde euch mit tausend Engeln unterstützen, die einander folgen.“",s:['q:8:9']},
  {q:"Wie nennt der Koran den Tag von Badr?",c:["Den Tag der Unterscheidung (Yaum al-Furqan)","Den Tag der Auferstehung","Den Tag des Festes","Den Tag der Hidschra"],b:0,e:"Der Tag, an dem die Wahrheit vom Irrtum unterschieden wurde.",s:['q:8:41']},
  {q:"Gegen welchen Stamm kämpften die Muslime bei Badr?",c:["Die Quraisch","Die Römer","Die Perser","Die Ansar"],b:0,e:"Das Heer der Quraisch kam aus Mekka.",s:['f:badr']},
  {q:"An welchem Tag des Ramadan fand die Schlacht von Badr statt?",c:["Am 17.","Am 27.","Am 1.","Am 10."],b:0,e:"Am 17. Ramadan im Jahr 2.",s:['f:badr']},
  {q:"In welcher Lage waren die Muslime laut dem Koran bei Badr?",c:["Sie waren schwach und gedemütigt","Sie waren sehr zahlreich","Sie waren reich","Sie waren zu Pferd"],b:0,e:"„Allah hat euch bei Badr geholfen, als ihr unterlegen wart.“",s:['q:3:123']}
 ]},
'h-fath':{titre:"Die Einnahme Mekkas",
 texte:["Im Jahr 8 nach der Hidschra (630), im Monat Ramadan, zog der Prophet ﷺ mit etwa 10.000 Muslimen in Mekka ein, fast ohne Kampf.",
  "Er vergab seinen früheren Feinden und reinigte die Kaaba von ihren 360 Götzen, wobei er rezitierte: „Die Wahrheit ist gekommen, und das Falsche ist vergangen.“",
  "Die Sure An-Nasr kündigt diese Hilfe Allahs an und dass die Menschen in Scharen in den Islam eintreten."],
 retenir:"Ramadan im Jahr 8: Mekka geöffnet, die Götzen zerschlagen, Vergebung gewährt.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"In welchem Jahr nach der Hidschra wurde Mekka eingenommen?",c:["Im Jahr 8","Im Jahr 2","Im Jahr 1","Im Jahr 11"],b:0,e:"Im Jahr 630 christlicher Zeitrechnung.",s:['f:fath']},
  {q:"In welchem Monat fand die Einnahme Mekkas statt?",c:["Ramadan","Schawwal","Dhul-Hiddscha","Muharram"],b:0,e:"Die Einnahme Mekkas fand im Ramadan statt.",s:['f:fath']},
  {q:"Wie viele Muslime ungefähr begleiteten den Propheten ﷺ bei der Einnahme Mekkas?",c:["Etwa 10.000","Etwa 313","Etwa 1000","Etwa 100"],b:0,e:"Ein Heer von etwa 10.000 Mann.",s:['f:fath']},
  {q:"Wie viele Götzen umgaben die Kaaba am Tag der Einnahme Mekkas?",c:["360","12","99","1000"],b:0,e:"Abdullah ibn Mas'ud berichtet, dass es 360 waren.",s:['h:idoles']},
  {q:"Welchen Vers rezitierte der Prophet ﷺ, als er die Götzen der Kaaba niederschlug?",c:["„Die Wahrheit ist gekommen, und das Falsche ist vergangen“","„Im Namen Allahs“","„Sag: Er ist Allah, ein Einziger“","„Lies!“"],b:0,e:"Das ist Vers 81 der Sure Al-Isra'.",s:['q:17:81','h:idoles']},
  {q:"Wie behandelte der Prophet ﷺ nach der Einnahme seine früheren mekkanischen Feinde?",c:["Er vergab ihnen","Er vertrieb sie","Er sperrte sie ein","Er verbannte sie nach Abessinien"],b:0,e:"Er gewährte den Mekkanern eine allgemeine Vergebung.",s:['f:fath']},
  {q:"Welche Sure kündigt „die Hilfe Allahs und den Sieg“ an?",c:["An-Nasr (110)","Al-Fath (48)","Al-Fil (105)","Al-Kauthar (108)"],b:0,e:"„Wenn die Hilfe Allahs kommt und der Sieg.“",s:['q:110:1']},
  {q:"Wie traten die Menschen laut der Sure An-Nasr in den Islam ein?",c:["In Scharen","Einer nach dem anderen, heimlich","Durch Zwang","Niemand trat ein"],b:0,e:"„Und du die Menschen in Scharen in die Religion Allahs eintreten siehst.“",s:['q:110:2']},
  {q:"Erfolgte die Einnahme Mekkas durch eine große Schlacht?",c:["Nein, fast ohne Kampf","Ja, die größte der Geschichte","Ja, ein Jahr lang","Ja, am Fuß des Berges Uhud"],b:0,e:"Die Stadt wurde friedlich geöffnet, fast ohne Kampf.",s:['f:fath']},
  {q:"Wozu fordert die Sure An-Nasr nach dem Sieg auf?",c:["Allah zu preisen und Ihn um Vergebung zu bitten","Sofort den Hadsch zu machen","Drei Tage zu fasten","Die Kaaba wieder aufzubauen"],b:0,e:"„Lobpreise deinen Herrn und bitte Ihn um Vergebung.“",s:['q:110:3']}
 ]},
'h-califes':{titre:"Die ersten vier Kalifen",
 texte:["Nach dem Tod des Propheten ﷺ im Jahr 632 folgten vier Kalifen aufeinander: Abu Bakr, Umar, Uthman und Ali. Man nennt sie die „rechtgeleiteten Kalifen“.",
  "Abu Bakr ließ den Koran von Zaid ibn Thabit in einer einzigen Sammlung zusammentragen. Unter Umar breitete sich der Islam aus, und der Hidschri-Kalender wurde eingeführt.",
  "Uthman ließ den Koran in mehreren Exemplaren abschreiben, die in die Provinzen geschickt wurden. Ali, Cousin und Schwiegersohn des Propheten ﷺ, war der vierte Kalif."],
 retenir:"Abu Bakr, Umar, Uthman, Ali: die vier rechtgeleiteten Kalifen.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"Wer war der erste Kalif nach dem Tod des Propheten ﷺ?",c:["Abu Bakr","Umar","Ali","Uthman"],b:0,e:"Abu Bakr, dann Umar, Uthman und Ali.",s:['f:califes']},
  {q:"Wie viele „rechtgeleitete Kalifen“ folgten auf den Propheten ﷺ?",c:["4","3","5","12"],b:0,e:"Man nennt sie al-Khulafa' ar-Raschidun.",s:['f:califes']},
  {q:"In welcher Reihenfolge regierten die ersten vier Kalifen?",c:["Abu Bakr, Umar, Uthman, Ali","Ali, Umar, Abu Bakr, Uthman","Umar, Abu Bakr, Ali, Uthman","Uthman, Ali, Umar, Abu Bakr"],b:0,e:"Von 632 bis 661.",s:['f:califes']},
  {q:"Unter welchem Kalifen wurde der Koran zum ersten Mal in einer einzigen Sammlung zusammengetragen?",c:["Abu Bakr","Umar","Uthman","Ali"],b:0,e:"Nach der Schlacht von Yamama, in der viele Koranrezitatoren getötet wurden.",s:['h:compilation']},
  {q:"Welcher Gefährte wurde unter Abu Bakr beauftragt, den Koran zusammenzutragen?",c:["Zaid ibn Thabit","Bilal","Khalid ibn al-Walid","Salman"],b:0,e:"Zaid ibn Thabit war Schreiber der Offenbarung gewesen.",s:['h:compilation']},
  {q:"Welcher Kalif ließ den Koran in mehreren Exemplaren abschreiben und in die Provinzen schicken?",c:["Uthman","Abu Bakr","Umar","Ali"],b:0,e:"Um die Rezitation in der ganzen muslimischen Welt zu vereinheitlichen.",s:['h:copies']},
  {q:"In welchem Verwandtschaftsverhältnis stand Ali zum Propheten ﷺ?",c:["Er war sein Cousin und Schwiegersohn","Er war sein Bruder","Er war sein Onkel","Er war sein Großvater"],b:0,e:"Ali war der Ehemann von Fatima, der Tochter des Propheten ﷺ.",s:['f:califes']},
  {q:"Welcher Kalif trug den Beinamen „al-Faruq“, der das Wahre vom Falschen unterscheidet?",c:["Umar","Abu Bakr","Uthman","Ali"],b:0,e:"Umar ibn al-Khattab.",s:['f:califes']},
  {q:"Welcher Kalif trug den Beinamen „as-Siddiq“, der Wahrhaftige?",c:["Abu Bakr","Umar","Uthman","Ali"],b:0,e:"Abu Bakr glaubte sofort alles, was der Prophet ﷺ berichtete.",s:['f:califes']},
  {q:"Welcher Kalif heiratete nacheinander zwei Töchter des Propheten ﷺ?",c:["Uthman","Umar","Abu Bakr","Ali"],b:0,e:"Daher sein Beiname „Dhun-Nurain“, der Mann mit den zwei Lichtern.",s:['f:califes']}
 ]}
},

/* Hinweise (historische oder praktische Quellen, ohne arabischen Text) */
faits:{
 mois:{titre:"Hinweis",texte:"Die 12 Hidschri-Monate: Muharram, Safar, Rabi' al-Awwal, Rabi' ath-Thani, Dschumada al-Ula, Dschumada al-Akhira, Radschab, Schaban, Ramadan, Schawwal, Dhul-Qa'da, Dhul-Hiddscha."},
 jeune2:{titre:"Historischer Hinweis",texte:"Das Fasten im Ramadan wurde in Medina vorgeschrieben, im Jahr 2 nach der Hidschra (624)."},
 conditions:{titre:"Hinweis",texte:"Die Gelehrten nennen als Bedingungen für die Fastenpflicht: Muslim sein, die Pubertät erreicht haben, geistig gesund und zum Fasten fähig sein."},
 aid:{titre:"Hinweis",texte:"Der Islam hat zwei Feste: das Ramadanfest (Eid al-Fitr) am 1. Schawwal, am Ende des Ramadan, und das Opferfest (Eid al-Adha) am 10. Dhul-Hiddscha, während des Hadsch."},
 shahada:{titre:"Hinweis",texte:"Wortlaut der Schahada: „Asch-hadu an la ilaha illa Llah, wa asch-hadu anna Muḥammadan rasulu Llah“ – „Ich bezeuge, dass es keinen Gott gibt außer Allah, und ich bezeuge, dass Muhammad der Gesandte Allahs ist“."},
 rakat:{titre:"Überlieferte Praxis",texte:"Die Zahl der Gebetseinheiten jedes Gebets stammt aus der Praxis des Propheten ﷺ, überliefert von allen Muslimen: Fadschr 2, Dhuhr 4, Asr 4, Maghrib 3, Ischa 4, also 17 Rak'at pro Tag."},
 zakat:{titre:"Hinweis",texte:"Die Zakat auf Geld beträgt 2,5 % (ein Vierzigstel) der Ersparnisse, die den Nisab erreichen und ein Mondjahr lang im Besitz bleiben (der Haul). Die Sadaqa ist eine freiwillige Spende. Für besondere Fälle sollte man einen Gelehrten fragen."},
 hajj:{titre:"Hinweis",texte:"Der Hadsch findet vom 8. bis 13. Dhul-Hiddscha statt. Der Pilger tritt in den Ihram ein (die Männer tragen zwei ungenähte weiße Tücher), vollzieht den Tawaf (sieben Umrundungen der Kaaba) und den Sa'y (siebenmal zwischen Safa und Marwa). Der 9. ist der Tag von Arafa, der 10. das Opferfest (Eid al-Adha)."},
 coran:{titre:"Hinweis",texte:"Der Koran hat nach der verbreitetsten Zählung 114 Suren und 6236 Verse. Er ist in 30 Teile (Dschuz') eingeteilt. Ein Vers heißt Aya. Die vor der Hidschra offenbarten Suren nennt man mekkanisch, die danach medinensisch. Die längste ist Al-Baqara (286 Verse)."},
 tawba:{titre:"Hinweis",texte:"Die Sure At-Tauba (9) ist die einzige der 114 Suren, die nicht mit „Bismi Llahi r-Raḥmani r-Raḥim“ beginnt."},
 ikhlas:{titre:"Hinweis",texte:"Al-Ikhlas bedeutet „der reine Monotheismus, die Aufrichtigkeit“: Die Sure reinigt den Glauben von jeder Beigesellung."},
 hawwa:{titre:"Hinweis",texte:"Der Koran erwähnt die Frau Adams, ohne sie zu nennen. Ihr Name, Hawwa' (Eva), stammt aus der Sunna und von den Gelehrten."},
 musa:{titre:"Hinweis",texte:"Musa ist der Prophet, der im Koran am häufigsten genannt wird: mehr als 130-mal."},
 maryam:{titre:"Hinweis",texte:"Maryam ist die einzige Frau, die im Koran mit Namen genannt wird. Die Sure 19 trägt ihren Namen."},
 sira:{titre:"Historischer Hinweis",texte:"Der Prophet ﷺ wurde um 570 in Mekka geboren, im Stamm der Quraisch. Er war vaterlos, verlor seine Mutter Amina mit 6 Jahren und wuchs bei seinem Großvater Abd al-Muttalib und dann bei seinem Onkel Abu Talib auf. Man nannte ihn al-Amin. Er starb 632 in Medina."},
 prophetes25:{titre:"Hinweis",texte:"25 Propheten werden im Koran mit Namen genannt. 18 von ihnen werden zusammen in der Sure Al-An'am (6), Verse 83 bis 86, erwähnt."},
 debuts:{titre:"Historischer Hinweis",texte:"Khadidscha, eine reiche Händlerin, heiratete den Propheten ﷺ, als er 25 Jahre alt war. Zu den allerersten Muslimen gehörten: Khadidscha, Abu Bakr, Ali (noch ein Kind), Zaid ibn Haritha. Bilal, ein verfolgter und dann freigelassener Sklave, wurde der erste Muezzin. Sumayya, die Mutter von Ammar, war die erste Märtyrerin."},
 hegire:{titre:"Historischer Hinweis",texte:"Die Hidschra fand 622 statt. Der Prophet ﷺ und Abu Bakr versteckten sich in der Höhle Thaur. Medina hieß Yathrib. Der Prophet ﷺ baute dort seine Moschee. Der Hidschri-Kalender wurde unter dem Kalifat von Umar eingeführt."},
 badr:{titre:"Historischer Hinweis",texte:"Die Schlacht von Badr fand am 17. Ramadan im Jahr 2 (624) statt. Etwa 313 Muslime standen fast 1000 Kämpfern der Quraisch gegenüber."},
 fath:{titre:"Historischer Hinweis",texte:"Mekka wurde im Ramadan des Jahres 8 (630) von etwa 10.000 Muslimen geöffnet, fast ohne Kampf. Der Prophet ﷺ gewährte den Mekkanern eine allgemeine Vergebung."},
 califes:{titre:"Historischer Hinweis",texte:"Die vier rechtgeleiteten Kalifen: Abu Bakr as-Siddiq (632–634), Umar al-Faruq (634–644), Uthman Dhun-Nurain (644–656), der zwei Töchter des Propheten ﷺ heiratete, Ruqayya und danach Umm Kulthum, und Ali (656–661), Cousin des Propheten ﷺ und Ehemann seiner Tochter Fatima."}
},

/* Zusammenfassungen für lange Hadithe (der vollständige Text bleibt zugänglich) */
resumes:{
 cinq:"Bei der Nachtreise (al-Isra' wa l-Mi'radsch) wurden zunächst fünfzig Gebete vorgeschrieben und dann auf fünf Gebete am Tag erleichtert.",
 enfants:"Ar-Rubayyi' bint Mu'awwidh berichtet, dass die Gefährten ihre kleinen Kinder am Tag von Aschura fasten ließen und ihnen Spielzeug aus Wolle gaben, damit sie bis zum Fastenbrechen durchhielten.",
 hira:"Aischa berichtet, dass sich der Prophet ﷺ in die Höhle Hira zurückzog. Der Engel kam und sagte zu ihm: „Lies!“. Er kehrte zu Khadidscha zurück, die ihn tröstete und ihn dann zu ihrem Cousin Waraqa ibn Naufal brachte.",
 regles:"Aischa erklärt, dass ihnen befohlen wurde, das während der Periode versäumte Fasten nachzuholen, nicht aber das Gebet.",
 tarawih:"Der Prophet ﷺ betete im Ramadan nachts in der Moschee; Menschen beteten hinter ihm, immer mehr. Dann ging er nicht mehr hinaus, aus Sorge, dieses Gebet könnte ihnen zur Pflicht gemacht werden.",
 adhan:"Der Gefährte Abdullah ibn Zaid sah im Traum die Worte des Adhan. Der Prophet ﷺ bestätigte diesen Traum und bat Bilal, den Ruf zu rufen, weil seine Stimme weiter trug.",
 ikhlas:"Ein Mann rezitierte immer wieder die Sure Al-Ikhlas und hielt das für wenig. Der Prophet ﷺ sagte: „Sie entspricht einem Drittel des Korans.“",
 kursi:"Der Prophet ﷺ fragte Ubayy ibn Ka'b, welcher der größte Vers im Buch Allahs sei. Er antwortete: Ayat al-Kursi. Der Prophet ﷺ beglückwünschte ihn zu seinem Wissen.",
 hajj_une:"Der Prophet ﷺ verkündete, dass der Hadsch vorgeschrieben sei. Ein Mann fragte: „Jedes Jahr?“ Er antwortete, wenn er Ja sagte, würde es jedes Jahr Pflicht: Er ist einmal Pflicht.",
 arafa:"Leute fragten den Propheten ﷺ auf Arafa nach der Pilgerfahrt. Er antwortete: „Der Hadsch ist Arafa.“",
 jibril:"Der Engel Dschibril befragte den Propheten ﷺ in Menschengestalt über den Islam, den Glauben und die Vollkommenheit (Ihsan). Der Glaube (Iman): an Allah glauben, an Seine Engel, Seine Bücher, Seine Gesandten, den Jüngsten Tag und die Vorherbestimmung, das Gute wie das Schlechte.",
 vie:"Ibn Abbas berichtet, dass der Prophet ﷺ mit 40 Jahren die Offenbarung empfing, 13 Jahre in Mekka blieb, nach Medina auswanderte, wo er 10 Jahre lebte, und mit 63 Jahren starb.",
 idoles:"Am Tag der Einnahme standen 360 Götzen um die Kaaba. Der Prophet ﷺ schlug mit einem Stock auf sie und rezitierte: „Die Wahrheit ist gekommen, und das Falsche ist vergangen.“",
 compilation:"Nach der Schlacht von Yamama, in der viele Koranrezitatoren getötet wurden, beauftragte Abu Bakr Zaid ibn Thabit, den Koran in einer einzigen Sammlung zusammenzutragen.",
 copies:"Uthman, besorgt über die Unterschiede in der Rezitation zwischen den Provinzen, ließ die Koransammlung in mehreren Exemplaren abschreiben und in jede Region schicken.",
 fitr_but:"Ibn Abbas berichtet, dass der Prophet ﷺ die Zakat al-Fitr vorgeschrieben hat, um den Fastenden von leerem und unanständigem Gerede zu reinigen und um den Armen zu essen zu geben.",
 afw:"Aischa fragte, was sie sagen solle, wenn sie die Nacht der Bestimmung erkenne. Er antwortete: „Sag: Allahumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿanni“ – O Allah, Du bist der Vergebende, Du liebst das Vergeben, so vergib mir."
}
};
